const icon = (name) => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const attr = esc;
const known = (value, fallback = 'Unknown') => value == null || value === '' ? fallback : esc(Array.isArray(value) ? value.join(', ') : value);
const human = (value) => String(value || '').replaceAll('_', ' ').replace(/\b\w/g, x => x.toUpperCase());
const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const fmt = (value) => Number.isFinite(Number(value)) ? Number(value).toLocaleString(undefined, {maximumFractionDigits:2}) : '—';
const date = (value, includeTime = false) => { if (!value) return 'Not yet'; const d = new Date(value); return Number.isNaN(d.getTime()) ? esc(value) : d.toLocaleDateString(undefined, {month:'short',day:'numeric',year:'numeric', ...(includeTime ? {hour:'numeric',minute:'2-digit'} : {})}); };
const safeUrl = (value) => { if (!value) return ''; try { const u = new URL(value, location.origin); return ['http:','https:'].includes(u.protocol) ? u.href : ''; } catch { return ''; } };
const list = (data) => Array.isArray(data) ? data : data?.items || [];
const isSimulation = (bridge) => ['simulation','simulate','dry_run'].includes(bridge?.mode);
const state = {route:'overview',beans:[],recipes:[],cards:[],jobs:[],status:{},settings:{},session:{},query:'',filter:'all',importProfile:null,refreshing:false,modalContext:null};
const trustedLan = () => (state.session.access_mode || state.settings.access_mode) === 'trusted_lan';
const navigation = [{id:'overview',label:'Overview',icon:'overview'},{id:'beans',label:'Bean library',icon:'bean'},{id:'recipes',label:'Recipes',icon:'recipe'},{id:'cards',label:'NFC cards',icon:'card'},{id:'settings',label:'Settings',icon:'settings'}];
const modal = $('#modal');
let modalReturnFocus = null;
let submitting = false;
let pendingImportLink = null;

function hydrateIcons(root = document) { $$('[data-icon]', root).forEach(el => { el.innerHTML = icon(el.dataset.icon); }); }
function toast(message, error = false) {
  const el = document.createElement('div'); el.className = `toast${error ? ' error' : ''}`; el.setAttribute('role', error ? 'alert' : 'status');
  el.innerHTML = `${icon(error ? 'warning' : 'check')}<span>${esc(message)}</span><button class="icon-button" aria-label="Dismiss notification">${icon('close')}</button>`;
  $('button', el).addEventListener('click', () => el.remove()); $('#toasts').append(el); setTimeout(() => el.remove(), error ? 10000 : 5500);
}
function detailMessage(detail) {
  if (typeof detail === 'string') return detail;
  if (Array.isArray(detail)) return detail.map(x => `${(x.loc || []).filter(x => x !== 'body').join(' › ')}: ${x.msg || JSON.stringify(x)}`).join('; ');
  return detail?.message || JSON.stringify(detail || 'The request could not be completed.');
}
async function api(path, options = {}) {
  const headers = {...(options.headers || {})};
  if (options.body && !(options.body instanceof FormData)) {headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  let response;
  try { response = await fetch(path, {credentials:'same-origin',cache:'no-store',...options,headers}); }
  catch { throw new Error('The local server could not be reached. Check that it is running and try again.'); }
  const data = response.status === 204 ? {} : await response.json().catch(() => ({}));
  if (!response.ok) { const error=new Error(detailMessage(data.detail || data.error || `Request failed (${response.status})`)); error.status=response.status; throw error; }
  return data;
}
async function withForm(form, fn) {
  if (submitting) return;
  submitting=true;const buttons=$$('button[type=submit]',form);buttons.forEach(b=>b.disabled=true);const error=$('.form-error',form);if(error)error.textContent='';
  try { await fn(); } catch(e) { if(error)error.textContent=e.message;else toast(e.message,true); }
  finally { submitting=false;buttons.forEach(b=>b.disabled=false); }
}
function openModal(title, subtitle, body, {wide=false,narrow=false,prefix=''}={}) {
  modalReturnFocus=document.activeElement;modal.className=`modal${wide?' wide':''}${narrow?' narrow':''}`;
  $('#modal-content').innerHTML=`<div class="modal-header"><div>${prefix?`<div class="modal-title-prefix">${esc(prefix)}</div>`:''}<h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;
  modal.setAttribute('aria-labelledby','modal-title');if(!modal.open)modal.showModal();modal.scrollTop=0;
}
function closeModal() {modal.close();state.modalContext=null;$('#modal-content').innerHTML='';document.body.classList.remove('login-only');modalReturnFocus?.focus?.();}
function showModalLoading(title) {openModal(title,'Loading the latest details…','<div class="loading-state"><span class="spinner"></span></div>');}
function field(name,label,value='',type='text',extra='',help='') {return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><input id="f-${attr(name)}" name="${attr(name)}" type="${attr(type)}" value="${attr(value ?? '')}" ${extra}>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function textarea(name,label,value='',extra='',help=''){return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><textarea id="f-${attr(name)}" name="${attr(name)}" ${extra}>${esc(value ?? '')}</textarea>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function selectField(name,label,value,options,extra=''){return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><select id="f-${attr(name)}" name="${attr(name)}" ${extra}>${options.map(o=>{const [val,text]=Array.isArray(o)?o:[o,human(o)];return `<option value="${attr(val)}" ${String(val)===String(value)?'selected':''}>${esc(text)}</option>`;}).join('')}</select></div>`;}
function callout(text,type='info',title=''){return `<div class="callout ${attr(type)}">${icon(type==='warning'||type==='danger'?'warning':'info')}<p>${title?`<strong>${esc(title)}</strong> `:''}${text}</p></div>`;}
function emptyState(title,description,action='',label='',symbol='bean',compact=false){return `<div class="empty-state${compact?' compact':''}"><span class="empty-icon">${icon(symbol)}</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${action?`<button class="button ${compact?'button-small button-outline':'button-primary'}" data-action="${attr(action)}">${icon('plus')}${esc(label)}</button>`:''}</div>`;}
function heading(title,description,actions='',eyebrow='YOUR COFFEE WORKSPACE'){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function button(action,label,symbol='plus',style='primary',data=''){return `<button class="button button-${attr(style)}" data-action="${attr(action)}" ${data}>${icon(symbol)}${esc(label)}</button>`;}
function beanName(id){return state.beans.find(b=>String(b.id)===String(id))?.name || 'Unassigned coffee';}
function cardLabel(id){return state.cards.find(c=>String(c.id)===String(id))?.label || 'Card';}
function cardBackupState(card){
  if(card.requires_manual_identity_reconciliation)return {label:'Manual review required',tone:'red'};
  if(card.needs_fresh_read)return {label:'Fresh read required',tone:'red'};
  if(card.verified_at)return {label:'Read-back verified',tone:''};
  if(num(card.hardware_backup_count)>0)return {label:'Hardware backup saved',tone:''};
  if(num(card.simulation_backup_count)>0)return {label:num(card.imported_backup_count)>0?'Reference + simulation':'Simulation only',tone:'orange'};
  if(num(card.imported_backup_count)>0)return {label:'Reference imported',tone:'gray'};
  return {label:num(card.backup_count)>0?'Backup records available':'Needs first backup',tone:'gray'};
}
function cardBackupPill(card){const status=cardBackupState(card);return `<span class="pill ${status.tone}">${status.label}</span>`;}
function recipeName(id){return state.recipes.find(r=>String(r.id)===String(id))?.name || 'No recipe assigned';}
function statusPill(status){const s=String(status||'unknown');const type=['verified','completed','succeeded','success','online'].includes(s)?'':['failed','error','unverified'].includes(s)?'red':['pending','queued','awaiting_confirmation','dry_run','simulated','simulation'].includes(s)?'orange':'gray';return `<span class="pill ${type}">${esc(human(s))}</span>`;}
function renderNavigation(){
  $('#navigation').innerHTML=navigation.map((n,i)=>`${i===4?'<div class="nav-divider"></div>':''}<a href="#${n.id}" class="nav-link${state.route===n.id?' active':''}" ${state.route===n.id?'aria-current="page"':''}>${icon(n.icon)}<span>${n.label}</span></a>`).join('');
  $('#breadcrumb').textContent=navigation.find(n=>n.id===state.route)?.label || 'Overview';
  $('#session-button').hidden=trustedLan()||!state.session.authenticated;
  $('#session-button').textContent=(state.session.username || 'B').charAt(0).toUpperCase();
  $('#access-label').textContent=trustedLan()?'Private LAN access':'Local workspace';
}
function coffeeArt(){return `<div class="hero-orbit"></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 240 240"><path d="M44 205h168" stroke="#a8b799"/><ellipse cx="134" cy="205" rx="58" ry="8" fill="#c7d2b6" stroke="none"/><path d="M106 33h66l-7 10h-53Z" fill="#e9eddc" stroke="#7b9071"/><path d="M112 43h53l-8 91h-37Z" fill="#e1e8d2" stroke="#7b9071"/><path d="M118 49h41l-7 64h-28Z" fill="#ccdabd" stroke="#8c9f7d"/><path d="M120 134h38v9h-38Z" fill="#829779" stroke="#7b9071"/><path d="M126 143v12m26-12v12"/><path d="M134 151v9m9-9v10" stroke-dasharray="2 3"/><path d="M101 166h74l-8 36h-58Z" fill="#f9f8e8" stroke="#7b9071"/><path d="M175 171h7c15 0 15 21-12 21" stroke="#7b9071" stroke-width="3"/><ellipse cx="138" cy="166" rx="37" ry="6" fill="#e2e8d5" stroke="#7b9071"/><ellipse cx="138" cy="167" rx="25" ry="3" fill="#9eaa86" stroke="none"/><path d="M103 145H83V62h22M170 62h13v97" stroke="#829479" stroke-width="4"/><path d="M81 202V63a7 7 0 0 1 7-7h17m64 0h11a7 7 0 0 1 7 7v139" stroke="#91a17f" stroke-width="3"/><path d="M71 204h127" stroke="#859875" stroke-width="4"/><path d="M55 145c9-7 15 3 6 11s-15 0-6-11Zm-3 10 12-10M198 112c9-7 15 3 6 11s-15 0-6-11Zm-3 10 12-10" stroke="#b1bb9d"/><path d="M51 74c-2-7 5-10 4-16m147 115c-2-7 5-10 4-16" stroke="#b1bb9d"/></svg></div>`;}
function overview(){
  const b=state.status.bridge||{};const hasRecipes=state.recipes.length>0;
  return `${heading('A little ritual. A better cup.','Your coffees, recipes, and cards. All in one familiar place.',`<div class="date-chip">${icon('calendar')}${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div>`)}
  <div class="stats-grid">${[['bean',state.beans.length,'Coffees in your library','beans'],['recipe',state.recipes.length,'Saved brew recipes','recipes'],['card',state.cards.length,'Cards in your collection','cards']].map(([i,v,l,r])=>`<a class="stat-card" href="#${r}"><div class="stat-icon">${icon(i)}</div><div><div class="stat-value">${v.toString().padStart(2,'0')}</div><div class="stat-label">${l}</div></div><span class="stat-arrow">${icon('arrow')}</span></a>`).join('')}</div>
  <div class="overview-grid"><div><section class="hero-card"><div class="hero-copy"><div class="eyebrow">FROM COFFEE BAG TO FIRST SIP</div><h2>${hasRecipes?'Your next good cup<br>is already taking shape.':'Make room for your<br>next favorite coffee.'}</h2><p>${hasRecipes?'Fine-tune a recipe, save it to a card, and enjoy your coffee just the way you like it.':'Bring in a coffee profile, shape your 18 g recipe, and make it part of your morning ritual.'}</p>${button(hasRecipes?'new-recipe':'import',hasRecipes?'Create a recipe':'Import a coffee profile',hasRecipes?'plus':'upload')}</div>${coffeeArt()}</section>
    <section><div class="section-heading"><div><h2>Your brew recipes</h2><p>Made by you. Refined with every cup.</p></div><a class="text-link" href="#recipes">View all ${icon('arrow')}</a></div>${hasRecipes?`<div class="recipe-list">${state.recipes.slice(0,3).map(recipeCard).join('')}</div>`:`<div class="panel">${emptyState('Your first recipe belongs here','Import an approved coffee profile or build a recipe from scratch. Every new version stays in your library.','new-recipe','Create a recipe','recipe')}</div>`}</section>
    ${state.jobs.length?`<section class="mt-16"><div class="section-heading"><h2>Recent card activity</h2><a class="text-link" href="#cards">View cards ${icon('arrow')}</a></div><div class="panel">${state.jobs.slice(0,4).map(jobItem).join('')}</div></section>`:''}
  </div><aside class="overview-aside"><section class="panel workflow-panel"><div class="panel-header"><div><h2>A simple brewing flow</h2><p>Three steps to your next cup.</p></div>${icon('coffee')}</div><div class="workflow">${[['1','Save your coffee','Add its origin, tasting notes, and a recipe you’ve reviewed.'],['2','Prepare your card','Back up, review, and approve a write from your Windows PC.'],['3','Tap. Brew. Enjoy.','Tap the card on your offline xBloom and make it your own.']].map(([n,t,d])=>`<div class="workflow-step"><span class="step-number">${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></section>
  <section class="panel bridge-panel"><div class="bridge-top"><span class="device-icon">${icon('device')}</span><div><h3>Windows card bridge</h3><p>Your connection to Proxmark</p></div></div>${statusPill(b.online?(isSimulation(b)?'simulation':'online'):'offline')}<p class="bridge-note">${b.online?`Connected${b.name?` as ${esc(b.name)}`:''}. ${isSimulation(b)?'Simulation is enabled. Physical cards will not be changed.':'Card writes wait for your confirmation.'}`:'Start the bridge on your Windows PC when you’re ready to read or write a card.'}</p><div class="mini-divider"></div><a class="text-link" href="#settings">Connection & settings ${icon('arrow')}</a></section></aside></div>`;
}
function beanCard(bean,index){
  const flavors=Array.isArray(bean.flavor_notes)?bean.flavor_notes:[];const photo=safeUrl(bean.photo_url);const colors=['#e9eadb','#e7e7d8','#eee5d9','#e2e9df'];
  return `<article class="bean-card"><div class="bean-art" style="background:${colors[index%colors.length]}">${photo?`<img src="${attr(photo)}" alt="${attr(bean.name)} coffee bag" loading="lazy">`:`<div class="bean-bag"><div class="bag-label">${icon('bean')}<span>${esc(bean.roaster||'Your coffee')}</span></div></div>`}<span class="origin-label">${known(bean.country,'Origin unknown')}</span></div><div class="bean-content"><div class="bean-roaster">${known(bean.roaster,'Roaster unknown')}</div><h2 class="bean-name">${esc(bean.name)}</h2><p class="bean-meta">${[bean.process,bean.roast_level].filter(Boolean).map(esc).join(' · ') || 'Add processing and roast details'}</p><div class="chips">${flavors.length?flavors.slice(0,4).map(f=>`<span class="chip">${esc(f)}</span>`).join(''):'<span class="chip">Tasting notes to discover</span>'}</div><div class="bean-footer"><span class="muted" style="font-size:10px">${bean.rating?`<span class="rating-stars" aria-label="${attr(bean.rating)} out of 5 stars">${'★'.repeat(Math.round(bean.rating))}${'☆'.repeat(5-Math.round(bean.rating))}</span>`:`${state.recipes.filter(r=>String(r.bean_id)===String(bean.id)).length} recipes`}</span><button class="button button-small button-outline" data-action="view-bean" data-id="${attr(bean.id)}">View coffee ${icon('arrow')}</button></div></div></article>`;
}
function beansPage(){const q=state.query.toLowerCase();const beans=state.beans.filter(b=>[b.name,b.roaster,b.country,b.process,...(b.flavor_notes||[])].some(v=>String(v||'').toLowerCase().includes(q)));return `${heading('Your bean library','A home for the coffees you love, and the ones you’re yet to discover.',button('new-bean','Add coffee'),'KNOW YOUR COFFEE')}<div class="toolbar"><div class="search-box">${icon('search')}<input id="page-search" type="search" placeholder="Search coffee, roaster, origin…" value="${attr(state.query)}" aria-label="Search coffees"></div><span class="record-count">${beans.length} ${beans.length===1?'coffee':'coffees'}</span></div><div id="results">${beans.length?`<div class="card-grid">${beans.map(beanCard).join('')}</div>`:`<div class="panel">${emptyState(q?'No coffees match your search':'Start with a coffee you love',q?'Try a different coffee name, roaster, or origin.':'Add details from your bag, fetch a product link, or import a profile you’ve reviewed.',q?'':'new-bean','Add your first coffee','bean')}</div>`}</div>`;}
function recipeCard(recipe){return `<article class="recipe-card"><div class="recipe-card-icon">${icon('recipe')}</div><div class="recipe-card-copy"><h3>${esc(recipe.name)}</h3><p class="recipe-card-subtitle">${esc(beanName(recipe.bean_id))} <span aria-hidden="true">·</span> Version ${num(recipe.version,1)}</p><div class="recipe-metrics"><div class="recipe-metric">${fmt(recipe.dose_g)} g<small>COFFEE</small></div><div class="recipe-metric">1:${fmt(recipe.ratio)}<small>RATIO</small></div><div class="recipe-metric">${fmt(recipe.total_water_ml)} ml<small>WATER</small></div><div class="recipe-metric">${recipe.pours?.length||0} pours<small>BREW STEPS</small></div></div></div><div class="recipe-card-actions"><span class="pill">${recipe.cup_type==='xpod'?'xPod':recipe.cup_type==='other'?'Other dripper':'Omni dripper'}</span><button class="button button-small button-outline" data-action="view-recipe" data-id="${attr(recipe.id)}">View recipe ${icon('arrow')}</button></div></article>`;}
function recipesPage(){const q=state.query.toLowerCase();const recipes=state.recipes.filter(r=>[r.name,beanName(r.bean_id)].some(v=>v.toLowerCase().includes(q)));return `${heading('Recipes worth repeating','Build your brew, keep every version, and find your sweet spot.',button('new-recipe','Create recipe'),'YOUR BREW NOTEBOOK')}<div class="toolbar"><div class="search-box">${icon('search')}<input id="page-search" type="search" placeholder="Search recipes or coffees…" value="${attr(state.query)}" aria-label="Search recipes"></div><span class="record-count">${recipes.length} ${recipes.length===1?'recipe':'recipes'}</span></div>${recipes.length?`<div class="recipe-list">${recipes.map(recipeCard).join('')}</div>`:`<div class="panel">${emptyState(q?'No recipes found':'Every good cup starts with a recipe',q?'Try a different recipe or coffee name.':'Begin with an 18 g recipe and adjust the pours, temperature, and grind to suit your coffee.',q?'':'new-recipe','Create your first recipe','recipe')}</div>`}`;}
function cardsPage(){return `${heading('Your card collection','Prepare a recipe, confirm your card, and keep a verified backup.',button('new-card','Register card'),'READY FOR YOUR NEXT BREW')}${callout('Each physical card gets its own label. Custom cards can share the same UID, so always match the label to the card on your reader.','info')}${state.cards.length?`<div class="card-inventory">${state.cards.map(c=>`<article class="nfc-card"><div class="nfc-card-heading"><span class="nfc-card-icon">${icon('card')}</span>${cardBackupPill(c)}</div><h3>${esc(c.label)}</h3><div class="nfc-uid mono">${c.uid?esc(c.uid):'UID recorded after first read'}</div><div class="status-row"><span>Saved recipe</span><strong>${c.recipe_id?esc(recipeName(c.recipe_id)):'Not assigned'}</strong></div><div class="status-row"><span>Saved backup records</span><strong>${num(c.backup_count)}</strong></div><div class="nfc-card-footer"><span class="muted" style="font-size:10px">Custom NFC card</span><button class="button button-small button-outline" data-action="view-card" data-id="${attr(c.id)}">Manage card ${icon('arrow')}</button></div></article>`).join('')}</div>`:`<div class="panel">${emptyState('A place for every coffee card','Give your custom card a physical label, then save a backup before preparing its first recipe.','new-card','Register your first card','card')}</div>`}${state.jobs.length?`<section class="mt-16"><div class="section-heading"><h2>Card activity</h2><button class="text-link" data-action="refresh">${icon('refresh')}Refresh</button></div><div class="panel">${state.jobs.slice(0,12).map(jobItem).join('')}</div></section>`:''}`;}
function jobItem(job){
  const detail=job.error||job.message||job.result?.message||'';
  const recovery=job.status==='running'&&!state.status.bridge?.online;
  return `<div class="job-item"><span class="job-icon">${icon(job.kind==='read'?'download':job.kind==='restore'?'refresh':'card')}</span><div class="job-copy"><strong>${esc(human(job.kind||'Card job'))} · ${esc(cardLabel(job.card_id))}</strong><small>${date(job.created_at,true)}${job.mode==='simulation'?' · Simulation only':''}${detail?` · ${esc(detail)}`:''}</small></div><div class="job-actions">${statusPill(job.status)}${job.status==='queued'?`<button class="text-link" data-action="cancel-job" data-id="${attr(job.id)}">Cancel</button>`:''}${recovery?`<button class="text-link danger-text" data-action="resolve-job" data-id="${attr(job.id)}">Resolve interruption</button>`:''}</div></div>`;
}
function settingsPage(){const b=state.status.bridge||{},lan=trustedLan();return `${heading('A workspace that stays yours','Manage local access, the Windows bridge, and your library backups.','','WORKSPACE SETTINGS')}<div class="settings-grid">${brewingDefaultsPanel()}<section class="panel settings-section"><h2>Workspace & access</h2><p>${lan?'Anyone on your allowed local network can use this workspace. Keep it private to your trusted devices.':'Your recipe manager runs on your own server. Keep access within your local network.'}</p><div class="status-row"><span>${lan?'Access':'Signed in as'}</span><strong>${lan?'Private LAN access':esc(state.session.username||'Local account')}</strong></div><div class="status-row"><span>Application version</span><strong>${esc(state.settings.version||'1.0')}</strong></div><div class="status-row"><span>xBloom connection</span><strong>Offline · NFC only</strong></div><div class="status-row"><span>Default coffee dose</span><strong>18 g</strong></div><div class="inline-actions">${button('create-api-token','Create import token','lock','outline')}${lan?'':button('logout','Sign out','logout','quiet')}</div><p class="privacy-caption">${icon('shield')}Tokens are shown once. Keep them in your local credentials.</p></section><section class="panel settings-section"><h2>Windows Proxmark bridge</h2><p>Keep your Windows PC and USB Proxmark connected when working with cards.</p><div class="status-row"><span>Connection</span>${statusPill(b.online?'online':'offline')}</div><div class="status-row"><span>Bridge mode</span><strong>${b.mode?esc(human(b.mode)):'Not connected'}</strong></div><div class="status-row"><span>Last seen</span><strong>${b.last_seen?date(b.last_seen,true):'Not yet'}</strong></div><div class="inline-actions">${button('bridge-help','Setup instructions','device','outline')}${button('create-bridge-token','Create bridge token','lock','quiet')}</div></section><section class="panel settings-section"><h2>Back up your coffee library</h2><p>Download an archive of your database, bag photos, and stored card backups. Keep a copy somewhere separate from the server.</p><ul class="settings-checklist"><li>${icon('check')}Bean profiles, ratings, and tasting notes</li><li>${icon('check')}Recipes and their complete version history</li><li>${icon('check')}Card records and saved dump files</li></ul><a class="button button-outline" href="/api/backup" download>${icon('download')}Download workspace backup</a></section><section class="panel settings-section"><h2>Import your next coffee</h2><p>Paste a roaster product link to fetch bean details, or load a JSON profile prepared with Codex. Review the facts and the separate recipe recommendation before saving.</p>${button('import','Review & import a profile','upload','outline')}<div class="settings-links"><button class="text-link" data-action="import-format">View the import format ${icon('arrow')}</button><p>Missing coffee details stay unknown. Recipe suggestions are recommendations, and NFC compatibility is checked separately.</p></div></section></div>`;}
function render(){renderNavigation();const pages={overview,beans:beansPage,recipes:recipesPage,cards:cardsPage,settings:settingsPage};$('#main').innerHTML=(pages[state.route]||overview)();hydrateIcons();if(state.route==='settings')bindBrewingDefaults();}
async function refresh({renderPage=true,quiet=false}={}){
  if(state.refreshing)return;state.refreshing=true;
  const load=()=>Promise.all([api('/api/status'),api('/api/beans'),api('/api/recipes'),api('/api/cards'),api('/api/jobs'),api('/api/settings')]);
  try {
    // A failed first connection has not established which access mode to use.
    if(!state.session.access_mode){
      state.session=await api('/api/session');
      renderNavigation();
      if(!state.session.authenticated){showAuth();return;}
    }
    let data;
    try {data=await load();}
    catch(e){
      if(e.status!==401||!trustedLan())throw e;
      // Renew LAN access for read requests only. Never replay a submitted action.
      state.session=await api('/api/session');
      if(!state.session.authenticated)throw e;
      data=await load();
    }
    const [status,beans,recipes,cards,jobs,settings]=data;Object.assign(state,{status,beans:list(beans),recipes:list(recipes),cards:list(cards),jobs:list(jobs),settings});$('#connection-banner').hidden=true;if(renderPage){render();openPendingImport();}if(state.modalContext?.type==='initialize-preview')updateInitializationAvailability();
  }
  catch(e){if(e.status===401&&!trustedLan()){state.session.authenticated=false;showAuth();}else if(quiet){$('#connection-banner').textContent=e.message;$('#connection-banner').hidden=false;}else throw e;}
  finally{state.refreshing=false;}
}
function openPendingImport(){
  if(pendingImportLink===null||!state.session.authenticated)return;
  const productUrl=pendingImportLink;pendingImportLink=null;
  importProfile(null,{productUrl});
}
function changeRoute(){
  const hash=location.hash.slice(1),split=hash.indexOf('?'),route=(split<0?hash:hash.slice(0,split))||'overview';
  pendingImportLink=route==='import'?new URLSearchParams(split<0?'':hash.slice(split+1)).get('url')||'':null;
  state.route=navigation.some(n=>n.id===route)?route:'overview';state.query='';$('#sidebar').classList.remove('open');$('#nav-backdrop').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');
  if(state.session.authenticated){render();openPendingImport();window.scrollTo(0,0);}
}
function showAuth(){
  if(trustedLan())return;
  const setup=!state.session.configured;document.body.classList.add('login-only');modal.className='modal narrow';modalReturnFocus=null;
  $('#modal-content').innerHTML=`<div class="auth-header"><div class="auth-mark" aria-hidden="true">✳</div><h2 id="modal-title">${setup?'Welcome to your coffee space.':'Welcome back.'}</h2><p>${setup?'Create your local account to start building your coffee library.':'Sign in to your local recipe workspace.'}</p></div><div class="auth-body"><form id="auth-form">${field('username','Username',state.session.username||'', 'text','required autocomplete="username" minlength="2" maxlength="64"')}${`<div class="mt-16">${field('password','Password','','password',`required autocomplete="${setup?'new-password':'current-password'}" ${setup?'minlength="12"':''}`,setup?'Choose a password with at least 12 characters.':'')}</div>`}${setup?`<div class="mt-16">${field('confirm_password','Confirm password','','password','required autocomplete="new-password" minlength="12"')}</div>`:''}<div class="form-error" role="alert"></div><button class="button button-primary" type="submit">${icon('lock')}${setup?'Create my workspace':'Sign in'}</button></form><p class="auth-footer">Your library stays on your own server.</p></div>`;
  modal.setAttribute('aria-labelledby','modal-title');if(!modal.open)modal.showModal();
  $('#auth-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const fd=new FormData(e.target);if(setup&&fd.get('password')!==fd.get('confirm_password'))throw new Error('The passwords do not match.');await api(setup?'/api/setup':'/api/session',{method:'POST',body:{username:fd.get('username'),password:fd.get('password')}});state.session=await api('/api/session');closeModal();await refresh();});});
}

// Coffee library
function editBean(id){const bean=state.beans.find(b=>String(b.id)===String(id))||{};state.modalContext={type:'bean',id};
  openModal(id?'Edit your coffee':'Add a coffee','Start with what you know. Leave unavailable details blank.',`<form id="bean-form"><section class="form-section"><h3>The essentials</h3><p>Information from the bag or roaster’s product page.</p><div class="field-grid">${field('name','Coffee name',bean.name,'text','required maxlength="160" placeholder="e.g. La Esperanza"')}${field('roaster','Roaster',bean.roaster,'text','maxlength="160" placeholder="Who roasted it?"')}<div class="span-full">${field('product_url','Original product URL',bean.product_url,'url','placeholder="https://roaster.com/coffee/…"')}</div>${field('roast_date','Roast date',bean.roast_date,'date')}${field('roast_level','Roast level',bean.roast_level,'text','placeholder="e.g. Light or medium"')}</div></section><section class="form-section"><h3>Where it comes from</h3><p>Unknown details will stay unknown.</p><div class="field-grid three">${field('country','Country',bean.country)}${field('region','Region',bean.region)}${field('farm','Farm / producer',bean.farm)}${field('elevation','Elevation',bean.elevation,'text','placeholder="e.g. 1,800–2,000 masl"')}${field('process','Process',bean.process,'text','placeholder="e.g. Washed"')}${field('variety','Variety',bean.variety,'text','placeholder="e.g. Bourbon"')}</div></section><section class="form-section"><h3>In the cup</h3><div class="field-grid"><div class="span-full">${field('flavor_notes','Roaster tasting notes',(bean.flavor_notes||[]).join(', '),'text','placeholder="Peach, honey, black tea"','Separate tasting notes with commas.')}</div><div class="span-full">${textarea('notes','Your tasting notes',bean.notes,'placeholder="What did you enjoy? What would you change next time?"')}</div>${selectField('rating','Your rating',bean.rating||'',[['','Not rated'],[1,'1 · Not for me'],[2,'2 · Okay'],[3,'3 · Good'],[4,'4 · Really good'],[5,'5 · A favorite']])}${field('photo','Coffee bag photo','','file','accept="image/jpeg,image/png,image/webp"','Optional. JPEG, PNG, or WebP.')}</div></section><div class="form-error" role="alert"></div><div class="form-actions">${id?`<button type="button" class="button button-danger left" data-action="delete-bean" data-id="${attr(id)}">${icon('trash')}Delete</button>`:''}<button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">${icon('check')}${id?'Save coffee':'Add to library'}</button></div></form>`,{wide:true});
  $('#bean-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const fd=new FormData(e.target);const data={};for(const k of ['name','roaster','product_url','country','region','farm','elevation','process','variety','roast_level','roast_date','notes'])data[k]=String(fd.get(k)||'').trim()||null;data.flavor_notes=String(fd.get('flavor_notes')||'').split(',').map(x=>x.trim()).filter(Boolean);data.rating=fd.get('rating')?Number(fd.get('rating')):null;data.notes=String(fd.get('notes')||'').trim();data.provenance=bean.provenance||{source:'manual',reviewed:'true'};const saved=await api(id?`/api/beans/${encodeURIComponent(id)}`:'/api/beans',{method:id?'PATCH':'POST',body:data});const photo=fd.get('photo');if(photo instanceof File&&photo.size){const upload=new FormData();upload.append('file',photo);try{await api(`/api/beans/${encodeURIComponent(saved.id)}/photo`,{method:'POST',body:upload});}catch(err){toast(`Coffee saved. Photo upload failed: ${err.message}`,true);}}closeModal();await refresh();toast(id?'Coffee updated.':'Coffee added to your library.');});});
}
function viewBean(id){const bean=state.beans.find(b=>String(b.id)===String(id));if(!bean)return;const recipes=state.recipes.filter(r=>String(r.bean_id)===String(id));const photo=safeUrl(bean.photo_url);const source=safeUrl(bean.product_url);openModal(bean.name,bean.roaster||'Roaster unknown',`${photo?`<div class="detail-photo"><img src="${attr(photo)}" alt="${attr(bean.name)} coffee bag"></div>`:''}<div class="badge-row">${bean.rating?`<span class="rating-stars" aria-label="${bean.rating} out of 5 stars">${'★'.repeat(Math.round(bean.rating))}${'☆'.repeat(5-Math.round(bean.rating))}</span>`:'<span class="pill gray">Not rated yet</span>'}<span class="pill gray">Source details</span></div><dl class="info-grid">${[['Country',bean.country],['Region',bean.region],['Farm / producer',bean.farm],['Elevation',bean.elevation],['Process',bean.process],['Variety',bean.variety],['Roast level',bean.roast_level],['Roast date',bean.roast_date?date(bean.roast_date):null]].map(([l,v])=>`<div><dt>${l}</dt><dd>${known(v)}</dd></div>`).join('')}</dl>${bean.flavor_notes?.length?`<div class="note-block"><h4>Roaster tasting notes</h4><div class="chips">${bean.flavor_notes.map(n=>`<span class="chip">${esc(n)}</span>`).join('')}</div></div>`:''}<div class="note-block"><h4>Your tasting notes</h4><p>${bean.notes?esc(bean.notes).replaceAll('\n','<br>'):'No tasting notes yet. Brew a cup and record what you notice.'}</p></div>${source?`<p class="source-facts">Original source: <a href="${attr(source)}" target="_blank" rel="noopener noreferrer">${esc(new URL(source).hostname)} ${icon('link')}</a></p>`:'<p class="source-facts">Original product URL unknown.</p>'}<div class="detail-divider"></div><div class="section-heading"><h2>Recipes for this coffee</h2><button class="text-link" data-action="new-recipe" data-bean="${attr(id)}">${icon('plus')}New recipe</button></div>${recipes.length?`<div class="recipe-list">${recipes.map(recipeCard).join('')}</div>`:emptyState('Find its best brew','Create an 18 g recipe for this coffee.','','','recipe',true)}<div class="form-actions"><button class="button button-outline" data-action="edit-bean" data-id="${attr(id)}">${icon('edit')}Edit coffee & tasting notes</button></div>`,{wide:true,prefix:'BEAN LIBRARY'});}

// Recipe editor and immutable version history
const defaultPours=()=>[{volume_ml:60,temperature_c:95,flow_ml_s:3.5,pattern:'spiral',pause_s:35,agitation_before:false,agitation_after:false},{volume_ml:76,temperature_c:94,flow_ml_s:3.5,pattern:'circle',pause_s:15,agitation_before:false,agitation_after:false},{volume_ml:76,temperature_c:93,flow_ml_s:3.5,pattern:'spiral',pause_s:15,agitation_before:false,agitation_after:false},{volume_ml:76,temperature_c:92,flow_ml_s:3.5,pattern:'center',pause_s:0,agitation_before:false,agitation_after:false}];
function newRecipeDefaults(){
  const saved=state.settings.brewing_defaults?.recipe_defaults;
  return saved&&typeof saved==='object'&&Array.isArray(saved.pours)?JSON.parse(JSON.stringify(saved)):{dose_g:18,ratio:16,total_water_ml:288,grind_setting:50,grinder_rpm:80,grinder_enabled:true,cup_type:'omni',pours:defaultPours(),notes:''};
}
function brewingDefaultsPanel(){
  const defaults=state.settings.brewing_defaults||{};
  return `<section class="panel settings-section"><h2>Your usual brewing setup</h2><p>Used for new recipes and the starting recommendation on your first product-link import. Saved recipes and loaded JSON profiles keep their own settings.</p><form id="brewing-defaults-form">${selectField('equipment_profile','Brewing equipment',defaults.equipment_profile||'omni',[['omni','Omni dripper'],['v60_01_melodrip','Hario V60 01 Clear + Melodrip']])}${defaults.manual_instructions?`<div class="note-block"><h4>${esc(defaults.label||'Manual preparation')}</h4><p>${esc(defaults.manual_instructions).replaceAll('\n','<br>')}</p></div>`:''}<p class="muted">Melodrip is placed by hand after the bloom. Its handling is not encoded on an NFC card. The V60 setup uses your moving adapter with automatic grinding enabled.</p><div class="form-error" role="alert"></div><div class="inline-actions"><button class="button button-outline" type="submit">${icon('check')}Save brewing default</button></div></form></section>`;
}
function bindBrewingDefaults(){
  const form=$('#brewing-defaults-form');if(!form)return;
  form.addEventListener('submit',e=>{e.preventDefault();withForm(form,async()=>{
    const equipment_profile=String(new FormData(form).get('equipment_profile')||'');
    if(!['omni','v60_01_melodrip'].includes(equipment_profile))throw new Error('Choose a supported brewing setup.');
    await api('/api/settings/brewing-defaults',{method:'PATCH',body:{equipment_profile}});await refresh();toast('Brewing default saved for future recipes.');
  });});
}
function pourEditor(p,index){return `<div class="step-editor" data-pour="${index}"><div class="step-editor-header"><strong>${index===0?'01 · Bloom':`${String(index+1).padStart(2,'0')} · Pour`}</strong><button type="button" class="icon-button" data-action="remove-pour" aria-label="Remove pour ${index+1}">${icon('trash')}</button></div><div class="field-grid four">${field(`volume_ml_${index}`,'Water (ml)',p.volume_ml,'number','required min="1" max="500" step="1" data-pour-field="volume_ml"')}${field(`temperature_c_${index}`,'Temperature (°C)',p.temperature_c,'number','required min="20" max="100" step="1" data-pour-field="temperature_c"')}${field(`flow_ml_s_${index}`,'Flow (ml/s)',p.flow_ml_s,'number','required min="0.1" max="10" step="0.1" data-pour-field="flow_ml_s"')}${field(`pause_s_${index}`,index===0?'Bloom pause (s)':'Pause after (s)',p.pause_s,'number','required min="0" max="300" step="1" data-pour-field="pause_s"')}${selectField(`pattern_${index}`,'Pour pattern',p.pattern||'circle',['center','circle','spiral'],'data-pour-field="pattern"')}<div class="field"><span class="field-label">Agitation</span><label class="check-field" style="margin-top:0"><input type="checkbox" data-pour-field="agitation_before" ${p.agitation_before?'checked':''}>Before pour</label><label class="check-field" style="margin-top:0"><input type="checkbox" data-pour-field="agitation_after" ${p.agitation_after?'checked':''}>After pour</label></div></div></div>`;}
function readPours(form){return $$('.step-editor',form).map(el=>{const p={};$$('[data-pour-field]',el).forEach(input=>{p[input.dataset.pourField]=input.type==='checkbox'?input.checked:input.tagName==='SELECT'?input.value:Number(input.value);});return p;});}
function recipeFromForm(form){const fd=new FormData(form);return {name:String(fd.get('name')||'').trim(),bean_id:fd.get('bean_id')||null,dose_g:Number(fd.get('dose_g')),ratio:Number(fd.get('ratio')),total_water_ml:Number(fd.get('total_water_ml')),grind_setting:Number(fd.get('grind_setting')),grinder_rpm:Number(fd.get('grinder_rpm')),grinder_enabled:fd.get('grinder_enabled')==='on',cup_type:fd.get('cup_type'),xid:String(fd.get('xid')||'').trim()||null,pours:readPours(form),notes:String(fd.get('notes')||'').trim(),dripper:String(fd.get('dripper')||'').trim()||null,filter:String(fd.get('filter')||'').trim()||null,water_profile:String(fd.get('water_profile')||'').trim()||null};}
function updateRecipeTotals(form){const pours=readPours(form),total=pours.reduce((s,p)=>s+num(p.volume_ml),0),target=num($('[name=total_water_ml]',form).value),dose=num($('[name=dose_g]',form).value);const el=$('#pour-total',form);if(el)el.innerHTML=`<span>Pours total <strong>${fmt(total)} ml</strong></span><span>Recipe target <strong>${fmt(target)} ml</strong></span><span class="${Math.abs(total-target)>.01?'total-warning':''}">${Math.abs(total-target)>.01?`${fmt(Math.abs(total-target))} ml ${total>target?'over':'under'} target`:`${icon('check')} Volumes match`}</span>`;}
function editRecipe(id,beanId){const old=state.recipes.find(r=>String(r.id)===String(id));const recipe=old||{...newRecipeDefaults(),name:'',bean_id:beanId||''};openModal(id?'Refine your recipe':'Create a brew recipe',id?'Saving creates a new version. Your previous recipe stays in the history.':'An 18 g starting point. Adjust the recipe for your coffee and taste.',`<form id="recipe-form"><section class="form-section"><h3>Name your brew</h3><div class="field-grid">${field('name','Recipe name',recipe.name,'text','required maxlength="160" placeholder="e.g. A bright morning cup"')}${selectField('bean_id','Coffee',recipe.bean_id||'',[['','No coffee selected'],...state.beans.map(b=>[b.id,`${b.name}${b.roaster?` · ${b.roaster}`:''}`])])}</div></section><section class="form-section"><h3>The foundation</h3><p>Your intended recipe. Card compatibility is checked before a write.</p><div class="field-grid four">${field('dose_g','Coffee dose (g)',recipe.dose_g,'number','required min="1" max="100" step="0.1"')}${field('ratio','Brew ratio (1:…)',recipe.ratio,'number','required min="1" max="100" step="0.001"')}${field('total_water_ml','Total water (ml)',recipe.total_water_ml,'number','required min="1" max="2000" step="1"')}${selectField('cup_type','Brewer type',recipe.cup_type||'omni',[['omni','Omni dripper'],['other','Other dripper'],['xpod','xPod']])}${field('grind_setting','Grind setting',recipe.grind_setting,'number','required min="1" max="200" step="1"')}${field('grinder_rpm','Grinder RPM',recipe.grinder_rpm,'number','required min="1" max="300" step="1"')}<div class="field"><span class="field-label">Grinder</span><label class="check-field" style="margin-top:8px"><input type="checkbox" name="grinder_enabled" ${recipe.grinder_enabled!==false?'checked':''}>Grind before brewing</label></div>${field('xid','Card text ID (optional)',recipe.xid,'text','maxlength="7" pattern="[ -~]{0,7}"','Up to seven plain-text characters.')}</div></section><section class="form-section"><h3>Your brewing setup</h3><p>Optional details for consistent recipes and tasting comparisons.</p><div class="field-grid three">${field('dripper','Dripper / brewer',recipe.dripper,'text','placeholder="e.g. Omni dripper 2"')}${field('filter','Filter',recipe.filter,'text','placeholder="e.g. xBloom paper"')}${field('water_profile','Water profile',recipe.water_profile,'text','placeholder="e.g. Filtered tap water"')}</div></section><section class="form-section"><div class="section-heading"><div><h3>Build your pours</h3><p>Pause is the wait after each pour. Set the first pause for your bloom.</p></div><button type="button" class="button button-small button-outline" data-action="add-pour">${icon('plus')}Add pour</button></div><div id="pour-editors">${(recipe.pours||defaultPours()).map(pourEditor).join('')}</div><div class="summary-strip" id="pour-total"></div></section><section class="form-section">${textarea('notes','Recipe & tasting notes',recipe.notes,'placeholder="Brewing intent, dripper/filter details, and what changed after tasting…"','Use these notes to explain why this version is different.')}</section><div id="recipe-preview"></div><div class="form-error" role="alert"></div><div class="form-actions">${id?`<button type="button" class="button button-danger left" data-action="delete-recipe" data-id="${attr(id)}">${icon('trash')}Delete</button>`:''}<button type="button" class="button button-outline" data-action="preview-recipe">Check NFC compatibility</button><button class="button button-primary" type="submit">${icon('check')}${id?'Save new version':'Save recipe'}</button></div></form>`,{wide:true});state.modalContext={type:'recipe',id};const form=$('#recipe-form');updateRecipeTotals(form);form.addEventListener('input',e=>{if(['dose_g','ratio'].includes(e.target.name)){const dose=num($('[name=dose_g]',form).value),ratio=num($('[name=ratio]',form).value);$('[name=total_water_ml]',form).value=Math.round(dose*ratio);}else if(e.target.name==='total_water_ml'){const dose=num($('[name=dose_g]',form).value);if(dose)$('[name=ratio]',form).value=(num(e.target.value)/dose).toFixed(3);}updateRecipeTotals(form);$('#recipe-preview').innerHTML='';});form.addEventListener('submit',e=>{e.preventDefault();withForm(form,async()=>{const data=recipeFromForm(form);if(!data.pours.length)throw new Error('Add at least one pour.');const total=data.pours.reduce((s,p)=>s+p.volume_ml,0);if(Math.abs(total-data.total_water_ml)>.01)throw new Error('Pour volumes must add up to the recipe’s total water.');await api(id?`/api/recipes/${encodeURIComponent(id)}`:'/api/recipes',{method:id?'PATCH':'POST',body:data});closeModal();await refresh();toast(id?'A new recipe version is saved.':'Recipe saved to your library.');});});}
function pourTimeline(recipe){let water=0;return `<div class="pour-timeline">${(recipe.pours||[]).map((p,i)=>{water+=num(p.volume_ml);return `<div class="pour-row"><div class="pour-number">${i+1}</div><div class="pour-copy"><h4>${i===0?'Bloom':`Pour ${i+1}`} · ${fmt(p.temperature_c)} °C</h4><p>${esc(human(p.pattern))} pattern · ${fmt(p.flow_ml_s)} ml/s${num(p.pause_s)?` · ${fmt(p.pause_s)} s pause`:''}${p.agitation_before?' · Agitate before':''}${p.agitation_after?' · Agitate after':''}</p></div><div class="pour-amount">${fmt(p.volume_ml)} ml<small>${fmt(water)} ml total</small></div></div>`;}).join('')}</div>`;}
function recipeMetrics(recipe){return `<div class="recipe-preview-grid">${[[`${fmt(recipe.dose_g)} g`,'COFFEE DOSE'],[`1:${fmt(recipe.ratio)}`,'BREW RATIO'],[`${fmt(recipe.total_water_ml)} ml`,'TOTAL WATER'],[`${fmt(recipe.grind_setting)}`,'GRIND SETTING']].map(([v,l])=>`<div class="metric-tile"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`;}
async function viewRecipe(id,version=null){const current=state.recipes.find(r=>String(r.id)===String(id));if(!current)return;showModalLoading('Your brew recipe');try{const versions=list(await api(`/api/recipes/${encodeURIComponent(id)}/versions`));const historical=version?versions.find(v=>Number(v.version)===Number(version)):null;const r=historical?.recipe||historical?.data||historical||current;const recipe={...current,...r};const old=version&&Number(version)!==Number(current.version);openModal(recipe.name,beanName(recipe.bean_id),`<div class="badge-row"><span class="pill ${old?'orange':''}">Version ${num(recipe.version,1)}${old?' · Previous version':''}</span><span class="pill gray">${recipe.cup_type==='xpod'?'xPod':recipe.cup_type==='other'?'Other dripper':'Omni dripper'}</span><span class="pill gray">${fmt(recipe.grinder_rpm)} RPM${recipe.grinder_enabled===false?' · Grinder off':''}</span></div>${recipeMetrics(recipe)}${recipe.dripper||recipe.filter||recipe.water_profile?`<dl class="info-grid"><div><dt>Dripper</dt><dd>${known(recipe.dripper,'Not recorded')}</dd></div><div><dt>Filter</dt><dd>${known(recipe.filter,'Not recorded')}</dd></div><div><dt>Water</dt><dd>${known(recipe.water_profile,'Not recorded')}</dd></div></dl>`:''}<div class="section-heading"><h2>Pour schedule</h2><span class="muted" style="font-size:10px">${recipe.pours?.length||0} steps</span></div>${pourTimeline(recipe)}${recipe.notes?`<div class="note-block"><h4>Recipe & tasting notes</h4><p>${esc(recipe.notes).replaceAll('\n','<br>')}</p></div>`:''}<details><summary>Version history · ${versions.length||1} saved ${versions.length===1?'version':'versions'}</summary><div class="details-content version-list">${versions.length?versions.map(v=>`<div class="version-item"><div><strong>Version ${num(v.version,1)}${Number(v.version)===Number(current.version)?' · Current':''}</strong><p>${date(v.created_at||v.updated_at,true)}</p></div><button class="button button-small button-outline" data-action="recipe-version" data-id="${attr(id)}" data-version="${attr(v.version)}">View</button></div>`).join(''):'<p class="muted">The first version is saved with this recipe.</p>'}</div></details><div class="form-actions"><button class="button button-outline" data-action="edit-recipe" data-id="${attr(id)}">${icon('edit')}Edit current recipe</button><button class="button button-primary" data-action="choose-card" data-id="${attr(id)}">${icon('card')}Prepare a card</button></div>`,{wide:true,prefix:'YOUR BREW RECIPE'});}catch(e){closeModal();toast(e.message,true);}}
function encodingField(value){const labels={dose_g:'Coffee dose',ratio:'Brew ratio',total_water_ml:'Total water',grind_setting:'Grind setting',grinder_rpm:'Grinder RPM',volume_ml:'Pour volume',temperature_c:'Temperature',flow_ml_s:'Flow rate',pause_s:'Pause'};const match=String(value||'').match(/^pours\[(\d+)\]\.(.+)$/);return match?`Pour ${Number(match[1])+1} · ${labels[match[2]]||human(match[2])}`:labels[value]||human(value||'Recipe value');}
function previewHtml(preview){
  const errors=preview.errors||[],diffs=preview.differences||[],warnings=preview.warnings||[],effective=preview.effective||preview.encoded_recipe||{};
  return `${errors.length?callout(errors.map(esc).join('<br>'),'danger','This recipe cannot be encoded yet.'):callout(preview.compatible===false?'This recipe needs adjustments before it can be written.':'The recipe can be represented on a compatible card. Review any changes below.','info','NFC compatibility')}
  ${warnings.length?callout(warnings.map(esc).join('<br>'),'warning'):''}
  ${diffs.length?`<div class="table-wrap"><table><thead><tr><th>Field</th><th>Intended</th><th>On card</th></tr></thead><tbody>${diffs.map(d=>typeof d==='string'?`<tr><td colspan="3">${esc(d)}</td></tr>`:`<tr><td>${esc(encodingField(d.field||d.path||d.message))}</td><td>${known(d.intended??d.original??d.requested,'—')}</td><td>${known(d.effective??d.encoded??d.actual,'—')}</td></tr>`).join('')}</tbody></table></div>`:!errors.length?'<p class="muted" style="font-size:11px">No encoding differences were reported.</p>':''}
  ${effective?.dose_g?`<details><summary>View the NFC-compatible recipe</summary><div class="details-content">${recipeMetrics(effective)}${pourTimeline(effective)}</div></details>`:''}`;
}

// Reviewed profile import
function sampleProfile(){return {schema_version:1,bean:{name:'Example coffee · replace before importing',roaster:null,product_url:null,country:null,region:null,farm:null,elevation:null,process:null,variety:null,roast_level:null,roast_date:null,flavor_notes:[],notes:'',provenance:{source:'synthetic-example',reviewed:'false'}},recipe:{name:'Example 18 g recipe',dose_g:18,ratio:16,total_water_ml:288,grind_setting:50,grinder_rpm:80,grinder_enabled:true,cup_type:'omni',pours:defaultPours(),notes:'AI starting recommendation. Adjust to your coffee, dripper, filter, and taste.'}};}
const importBeanFields=[['name','Coffee name'],['roaster','Roaster'],['country','Country'],['region','Region'],['farm','Farm / producer'],['elevation','Elevation'],['process','Process'],['variety','Variety'],['roast_level','Roast level'],['roast_date','Roast date'],['product_url','Original product URL']];
const cloneProfile=profile=>JSON.parse(JSON.stringify(profile));
function parseImportProfile(text){
  let profile;try{profile=JSON.parse(text);}catch{throw new Error('The profile is not valid JSON. Check its braces, quotes, and commas.');}
  if(!profile||profile.schema_version!==1||!profile.bean||typeof profile.bean!=='object'||Array.isArray(profile.bean)||(profile.bean.flavor_notes!==undefined&&(!Array.isArray(profile.bean.flavor_notes)||profile.bean.flavor_notes.some(note=>typeof note!=='string')))||!profile.recipe||typeof profile.recipe!=='object'||!Array.isArray(profile.recipe.pours)||profile.recipe.pours.some(p=>!p||typeof p!=='object'||Array.isArray(p)))throw new Error('Use a version 1 coffee profile with bean details, a recipe, and its pours.');
  profile.recipe={dose_g:18,ratio:16,total_water_ml:288,grind_setting:60,grinder_rpm:80,grinder_enabled:true,cup_type:'omni',...profile.recipe};
  profile.recipe.pours=profile.recipe.pours.map(p=>({pattern:'circle',pause_s:0,agitation_before:false,agitation_after:false,...p}));
  return profile;
}
function applyImportBeanEdits(profile,values){
  const draft=cloneProfile(profile),bean=draft.bean;
  bean.provenance={...(bean.provenance||{})};
  for(const [key,value] of Object.entries(values)){
    const previous=bean[key]??(Array.isArray(value)?[]:value===''?'':null);
    if(JSON.stringify(previous)!==JSON.stringify(value)){
      const source=bean.provenance[key];
      if(!String(source||'').startsWith('User edited before import.'))bean.provenance[key]='User edited before import.'+(source?' Previous source: '+source:' No roaster source claimed.');
    }
    bean[key]=value;
  }
  return draft;
}
function mergeFetchedProfile(current,result){
  const fetched=parseImportProfile(JSON.stringify(result.profile));
  if(!current){fetched.recipe={...fetched.recipe,...newRecipeDefaults()};return fetched;}
  const draft=cloneProfile(current),incoming=fetched.bean;
  const productIdentity=value=>{try{const url=new URL(value);url.hash='';url.pathname=url.pathname.replace(/\/+$/,'');return url.href;}catch{return null;}};
  const oldSource=productIdentity(draft.bean?.product_url),newSource=productIdentity(result.source_url||incoming.product_url);
  // Never carry facts from a different coffee into fields the new source leaves unknown.
  const prior=oldSource&&oldSource===newSource?draft.bean:{};
  const hasValue=value=>Array.isArray(value)?value.length>0:value!==null&&value!==undefined&&value!=='';
  draft.bean={...prior,...incoming,provenance:{...(prior.provenance||{}),...(incoming.provenance||{})}};
  for(const key of [...importBeanFields.map(([key])=>key),'flavor_notes','notes','rating']){
    if(hasValue(prior[key])&&(!hasValue(incoming[key])||['notes','rating'].includes(key))){
      draft.bean[key]=prior[key];
      draft.bean.provenance[key]=prior.provenance?.[key]||'Retained from the supplied profile; not newly fetched.';
    }
  }
  // Fetching bean facts never replaces an existing recipe or its extra settings.
  draft.recipe=current.recipe?cloneProfile(current.recipe):fetched.recipe;
  return draft;
}
function readImportDraft(form){
  if(!state.importProfile||!form)return state.importProfile;
  const fd=new FormData(form),values={};
  for(const [key] of importBeanFields)values[key]=String(fd.get('bean_'+key)||'').trim()||null;
  values.notes=String(fd.get('bean_notes')||'').trim();
  values.rating=fd.get('bean_rating')?Number(fd.get('bean_rating')):null;
  const flavors=String(fd.get('bean_flavor_notes')||'').trim();
  values.flavor_notes=flavors===(state.importProfile.bean.flavor_notes||[]).join(', ')?state.importProfile.bean.flavor_notes||[]:flavors.split(',').map(x=>x.trim()).filter(Boolean);
  const draft=applyImportBeanEdits(state.importProfile,values);
  $$('[data-import-recipe]',form).forEach(input=>{
    const key=input.dataset.importRecipe;
    draft.recipe[key]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value.trim()||(['name','notes'].includes(key)?'':null);
  });
  draft.recipe.pours=readPours(form);
  return draft;
}
function importRecipeFields(recipe){
  const rf=(key,label,type='text',extra='',help='')=>field(key,label,recipe[key],type,extra+' data-import-recipe="'+key+'"',help);
  return '<section class="form-section"><h3>'+ (recipe.recommendation===false?'Your supplied recipe':'Brewing recommendation')+'</h3><p>Recipe settings are a starting point for your taste, separate from the roaster’s bean facts. Fetching bean details keeps your current recipe.</p><div class="field-grid">'+rf('name','Recipe name','text','required maxlength="160"')+selectField('cup_type','Brewer type',recipe.cup_type||'omni',[['omni','Omni dripper'],['other','Other dripper'],['xpod','xPod']],'data-import-recipe="cup_type"')+rf('dose_g','Coffee dose (g)','number','required min="0.1" max="100" step="0.1"')+rf('ratio','Brew ratio (1:…)','number','required min="1" max="100" step="0.001"')+rf('total_water_ml','Total water (ml)','number','required min="1" max="2000" step="0.1"')+rf('grind_setting','Grind setting','number','required min="0" max="200" step="0.1"')+rf('grinder_rpm','Grinder RPM','number','required min="0" max="300" step="1"')+'<div class="field"><span class="field-label">Grinder</span><label class="check-field"><input type="checkbox" data-import-recipe="grinder_enabled" '+(recipe.grinder_enabled!==false?'checked':'')+'>Grind before brewing</label></div></div><details><summary>Brewing setup and recipe notes</summary><div class="field-grid mt-16">'+rf('xid','Card text ID','text','maxlength="7"')+rf('dripper','Dripper / brewer')+rf('filter','Filter')+rf('water_profile','Water profile')+'<div class="span-full">'+textarea('notes','Recipe notes',recipe.notes,'data-import-recipe="notes"')+'</div></div></details></section><section class="form-section"><div class="section-heading"><div><h3>Pour schedule</h3><p>Adjust pour amounts to match the total water.</p></div><button type="button" class="button button-small button-outline" data-action="import-add-pour">'+icon('plus')+'Add pour</button></div><div id="pour-editors">'+recipe.pours.map((p,i)=>pourEditor(p,i).replace('data-action="remove-pour"','data-action="import-remove-pour"')).join('')+'</div><div class="summary-strip" id="pour-total"></div></section>';
}
function importProfile(profile=null,{productUrl=null,warnings=null,recipeRetained=false}={}){
  const initial=profile||state.importProfile;
  state.importProfile=initial?cloneProfile(initial):null;
  if(warnings!==null)state.importWarnings=warnings;
  const bean=initial?.bean||{},link=productUrl??bean.product_url??'';
  const context={type:'import'};
  const beanFields=importBeanFields.map(([key,label])=>field('bean_'+key,label,bean[key],key==='product_url'?'url':'text',(key==='name'?'required maxlength="160"':'placeholder="Unknown"'))).join('');
  const draftHtml=initial?'<form id="import-form"><section class="form-section"><h3>Bean facts</h3><p>Check details against the product page. Blank fields remain unknown. Corrections are recorded as your edits.</p><div class="field-grid">'+beanFields+'<div class="span-full">'+field('bean_flavor_notes','Roaster tasting notes',(bean.flavor_notes||[]).join(', '),'text','placeholder="Unknown"','Separate tasting notes with commas.')+'</div><div class="span-full">'+textarea('bean_notes','Your tasting notes',bean.notes)+'</div>'+selectField('bean_rating','Your rating',bean.rating||'',[['','Not rated'],[1,'1 · Not for me'],[2,'2 · Okay'],[3,'3 · Good'],[4,'4 · Really good'],[5,'5 · A favorite']])+'</div><div id="import-provenance">'+reviewSourceDetails(bean)+'</div></section>'+importRecipeFields(initial.recipe)+'<div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">Review profile '+icon('arrow')+'</button></div></form>':'';
  openModal('Bring in a coffee profile','Fetch bean facts from a product link. Review the separate recipe recommendation before saving.',
    '<div class="progress-steps"><span class="current"><b>1</b>Add details</span><i class="progress-line"></i><span><b>2</b>Review</span><i class="progress-line"></i><span><b>3</b>Save to library</span></div><form id="product-link-form" class="form-section"><div class="field"><label for="product-url">Product link</label><input id="product-url" name="url" type="url" required maxlength="2048" value="'+attr(link)+'" placeholder="https://roaster.com/products/your-coffee"><small>Fetches available bean facts. Missing details stay unknown; your existing recipe is kept.</small></div><div class="inline-actions mt-16"><button class="button button-primary" type="submit">'+icon('download')+'Fetch bean details</button><span id="import-fetch-status" role="status" aria-live="polite"></span></div><div class="form-error" role="alert"></div></form>'+
    (state.importWarnings?.length?callout(state.importWarnings.map(esc).join('<br>'),'warning'):'')+(recipeRetained?callout('Bean details fetched. Your existing recipe has been kept.','info'):'')+
    draftHtml+'<details id="import-json-details" class="import-json"><summary>Import a JSON file or paste a profile</summary><form id="import-json-form" class="mt-16"><p class="muted">Load a reviewed profile into the editor. This replaces the draft above; nothing is saved yet.</p><div class="file-drop">'+icon('upload')+'<label for="profile-file">Choose a JSON profile.</label><input id="profile-file" type="file" accept="application/json,.json"></div><div class="field"><label for="profile-json">Structured coffee profile</label><textarea id="profile-json" class="code-area" required spellcheck="false" placeholder=\'{"schema_version": 1, "bean": {...}, "recipe": {...}}\'></textarea></div><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="text-link left" data-action="load-example">Load a labeled example</button><button class="button button-outline" type="submit">Load profile into editor '+icon('arrow')+'</button></div></form></details>',{wide:true});
  state.modalContext=context;
  $('#product-link-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{
    const url=$('#product-url').value.trim();let parsed;try{parsed=new URL(url);}catch{throw new Error('Enter the full product link, starting with https://.');}
    if(parsed.protocol!=='https:'||(parsed.port&&parsed.port!=='443'))throw new Error('Use an https product link on the standard secure port.');
    $('#import-fetch-status').textContent='Fetching bean details…';
    try{
      const result=await api('/api/import/from-url',{method:'POST',body:{url}});
      if(state.modalContext!==context)return;
      const current=readImportDraft($('#import-form'));
      importProfile(mergeFetchedProfile(current,result),{productUrl:result.source_url,warnings:result.warnings||[],recipeRetained:!!current?.recipe});
    }finally{if(state.modalContext===context)$('#import-fetch-status').textContent='';}
  });});
  $('#profile-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){toast('Choose a JSON file smaller than 2 MB.',true);return;}$('#profile-json').value=await file.text();});
  $('#import-json-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const draft=parseImportProfile($('#profile-json').value);importProfile(draft,{warnings:[]});});});
  const form=$('#import-form');
  if(form){
    updateRecipeTotals(form);
    form.addEventListener('input',e=>{
      if(['dose_g','ratio'].includes(e.target.name))$('[name=total_water_ml]',form).value=Math.round(num($('[name=dose_g]',form).value)*num($('[name=ratio]',form).value)*100)/100;
      else if(e.target.name==='total_water_ml'){const dose=num($('[name=dose_g]',form).value);if(dose)$('[name=ratio]',form).value=(num(e.target.value)/dose).toFixed(3);}
      state.importProfile=readImportDraft(form);updateRecipeTotals(form);
      if(e.target.name?.startsWith('bean_'))$('#import-provenance').innerHTML=reviewSourceDetails(state.importProfile.bean);
    });
    form.addEventListener('submit',e=>{e.preventDefault();withForm(form,async()=>{
      const draft=readImportDraft(form);if(!draft.recipe.pours.length)throw new Error('Add at least one pour.');
      const preview=await api('/api/import/preview',{method:'POST',body:{profile:draft}});
      state.importProfile=draft;showImportReview(draft,preview);
    });});
  }
}

function reviewSourceDetails(bean){
  const fields=[['name','Coffee name'],['roaster','Roaster'],['country','Country'],['region','Region'],['farm','Farm / producer'],['elevation','Elevation'],['process','Process'],['variety','Variety'],['roast_level','Roast level'],['roast_date','Roast date']];
  const source=safeUrl(bean.product_url),photo=safeUrl(bean.photo_url);
  const provenance=Object.entries(bean.provenance||{});
  const rendered=new Set([...fields.map(([key])=>key),'product_url','photo_url','flavor_notes','notes','rating','provenance']);
  const additional=Object.entries(bean).filter(([key])=>!rendered.has(key));
  return `<details class="source-review"><summary>All coffee & source details</summary><div class="details-content">
    <dl class="info-grid">${fields.map(([key,label])=>`<div><dt>${label}</dt><dd>${known(bean[key])}</dd></div>`).join('')}<div><dt>Your rating</dt><dd>${bean.rating?`${esc(bean.rating)} / 5`:'Not rated'}</dd></div></dl>
    <div class="note-block"><h4>Original product URL</h4><p class="break">${source?`<a href="${attr(source)}" target="_blank" rel="noopener noreferrer">${esc(bean.product_url)}</a>`:'Unknown'}</p></div>
    <div class="note-block"><h4>Roaster tasting notes</h4><p>${bean.flavor_notes?.length?bean.flavor_notes.map(esc).join(', '):'Unknown'}</p></div>
    <div class="note-block"><h4>Your tasting notes</h4><p>${bean.notes?esc(bean.notes).replaceAll('\n','<br>'):'None supplied'}</p></div>
    ${photo?`<div class="note-block"><h4>Coffee bag photo</h4><p class="break"><a href="${attr(photo)}" target="_blank" rel="noopener noreferrer">${esc(bean.photo_url)}</a></p></div>`:''}
    <h4>Where these details came from</h4>${provenance.length?`<dl class="source-provenance">${provenance.map(([key,value])=>`<div><dt>${esc(human(key))}</dt><dd>${esc(typeof value==='string'?value:JSON.stringify(value)).replaceAll('\n','<br>')}</dd></div>`).join('')}</dl>`:'<p class="muted" style="font-size:11px">No field-level source notes were supplied.</p>'}
    ${additional.length?`<h4>Additional supplied details</h4><dl class="source-provenance">${additional.map(([key,value])=>`<div><dt>${esc(human(key))}</dt><dd>${known(typeof value==='object'&&value!==null?JSON.stringify(value):value)}</dd></div>`).join('')}</dl>`:''}
  </div></details>`;
}
