// Physical card inventory, backups, and explicitly approved jobs
const initializationProfile='iso15693_gen2_64_factory';
const initializationMode=()=>['hardware','simulation'].includes(state.status.bridge?.mode)?state.status.bridge.mode:'hardware';
const initializationBridgeReady=mode=>state.status.bridge?.online&&state.status.bridge.mode===mode&&Array.isArray(state.status.bridge.capabilities)&&state.status.bridge.capabilities.includes('init_factory_gen2_v1');
function newestModeBackup(backups,mode){return [...backups].filter(b=>b.source===mode).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')))[0];}
function initializationManualReview(card,mode){return Array.isArray(card.manual_identity_reconciliation_modes)?card.manual_identity_reconciliation_modes.includes(mode):card.requires_manual_identity_reconciliation===true;}
function initializationBlocked(card,mode){return card.type!=='custom'||initializationManualReview(card,mode)||(Array.isArray(card.needs_fresh_read_modes)?card.needs_fresh_read_modes.includes(mode):card.needs_fresh_read===true);}
function initializationCandidate(backup,mode,kind){return backup?.source===mode&&backup.initialization_native_json===true&&backup.block_count===64&&backup.block_size===4&&backup[kind==='blank'?'initialization_blank_candidate':'initialization_template_candidate']===true;}
function renderInitializationEntry(card,backups){
  const mode=initializationMode(),backup=newestModeBackup(backups,mode),actions=$('.form-actions',$('#modal-content'));
  if(!actions)return;
  if(initializationManualReview(card,mode)){
    const notice=document.createElement('div');notice.innerHTML=callout('Initialization was interrupted or could not be verified. The card’s identity or hidden settings may have changed. A new read records evidence but does not clear this restriction. Manual review is required; no automatic retry or rollback is available.','danger','Manual identity review required.');actions.before(notice);
    $$('[data-action="choose-recipe"],[data-action="restore-card"]',$('#modal-content')).forEach(b=>{b.disabled=true;b.title='Manual identity review is required.';});return;
  }
  const blank=backup?.block_count===64&&/^0{512}$/.test(backup.memory_hex||'');
  if(blank){const prepare=$('[data-action="choose-recipe"]',actions);if(prepare){prepare.disabled=true;prepare.title='A blank card needs a separate initialization review.';}}
  if(initializationBlocked(card,mode)||!initializationCandidate(backup,mode,'blank'))return;
  const entry=document.createElement('section');entry.className='form-section';
  entry.innerHTML=`<h3>${mode==='simulation'?'Simulated blank card':'Blank card setup'}</h3><p>This saved read matches the supported 64-block blank-card profile. Initialization changes its identity and two hidden chip settings, separately from a recipe write.</p>${button('initialize-card',mode==='simulation'?'Review simulated initialization':'Review blank-card initialization','card','outline',`data-id="${attr(card.id)}"`)}`;
  actions.before(entry);
}
function editCard(id){const card=state.cards.find(c=>String(c.id)===String(id))||{};openModal(id?'Edit card details':'Register a custom card','Give the physical card a label you can recognize on your desk.',`<form id="card-form"><div class="field-grid"><div class="span-full">${field('label','Physical card label',card.label,'text','required maxlength="100" placeholder="e.g. Green card · 01"','Put this label on the card so duplicate UIDs cannot cause confusion.')}</div><div class="span-full">${field('uid','UID (optional until first read)',card.uid,'text','pattern="[0-9A-Fa-f :\\-]{16,24}" placeholder="E0…"','Use the UID displayed by Proxmark. Multiple cards may share a UID.')}</div><div class="span-full">${textarea('notes','Card notes',card.notes,'placeholder="Color, identifying marks, or details about this tag…"')}</div></div><div class="form-error" role="alert"></div><div class="form-actions">${id?`<button type="button" class="button button-danger left" data-action="delete-card" data-id="${attr(id)}">${icon('trash')}Delete record</button>`:''}<button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">${icon('check')}${id?'Save details':'Register card'}</button></div></form>`);$('#card-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const fd=new FormData(e.target),data={label:String(fd.get('label')).trim(),uid:String(fd.get('uid')||'').replace(/[ :\-]/g,'').toUpperCase()||null,type:'custom',notes:String(fd.get('notes')||'').trim()};await api(id?`/api/cards/${encodeURIComponent(id)}`:'/api/cards',{method:id?'PATCH':'POST',body:data});closeModal();await refresh();toast(id?'Card details updated.':'Card registered. Save its first backup next.');});});}
async function viewCard(id){const card=state.cards.find(c=>String(c.id)===String(id));if(!card)return;showModalLoading(card.label);try{const backups=list(await api(`/api/cards/${encodeURIComponent(id)}/backups`));state.modalContext={type:'card',id,backups};openModal(card.label,'Match this label to the physical card before any read or write.',`<div class="badge-row"><span class="pill gray">Custom NFC card</span>${card.verified_at?'<span class="pill">Read-back verified</span>':'<span class="pill orange">Not verified on device</span>'}</div><dl class="info-grid"><div><dt>UID</dt><dd class="mono">${known(card.uid,'Not read yet')}</dd></div><div><dt>Inventory ID</dt><dd class="mono">${esc(card.id)}</dd></div><div><dt>Current recipe</dt><dd>${card.recipe_id?esc(recipeName(card.recipe_id)):'Not assigned'}</dd></div></dl>${card.notes?`<div class="note-block"><p>${esc(card.notes)}</p></div>`:''}${card.needs_fresh_read?callout('The previous operation was interrupted or failed. Read this card again before another write.','danger','Fresh read required.'):''}${!backups.length?callout('Read this physical card with the Windows bridge before writing. You can also import a reference dump to preview recipes.','warning','First, preserve the original.'):''}<div class="section-heading"><div><h2>Card backups</h2><p>Saved contents are retained for read-back checks and recovery.</p></div><button class="text-link" data-action="import-card-backup" data-id="${attr(id)}">${icon('upload')}Import dump</button></div>${backups.length?`<div class="table-wrap"><table><thead><tr><th>Saved backup</th><th>Contents</th><th>Actions</th></tr></thead><tbody>${backups.map((backup,i)=>`<tr><td><strong>${String(backup.source||'').startsWith('failed-readback-')?'Failed readback evidence':backup.original?'Original backup':`Backup ${backups.length-i}`}</strong><small>${date(backup.created_at,true)}</small></td><td><code>${esc((backup.sha256||backup.hash||backup.id).slice(0,12))}…</code><small>${backup.block_count?`${backup.block_count} blocks · `:''}${backup.source==='import'?'Imported reference':backup.source==='simulation'?'Simulation':backup.source==='hardware'?'Hardware read':String(backup.source||'').startsWith('failed-readback-')?'Failed readback evidence':'Unrecognized backup source'}</small></td><td><div class="inline-actions"><a class="icon-button" aria-label="Download backup" href="/api/cards/${encodeURIComponent(id)}/backups/${encodeURIComponent(backup.id)}/download" download>${icon('download')}</a><button class="button button-small button-outline" data-action="restore-card" data-id="${attr(id)}" data-backup="${attr(backup.id)}" ${!['hardware','simulation'].includes(backup.source)?'disabled title="Only successful hardware or simulation backups can be restored"':''}>Restore</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('No backup saved yet','Read the card with your Windows bridge, or import the JSON dump from a read of this card.','','','folder',true)}<div class="form-actions"><button class="button button-quiet left" data-action="edit-card" data-id="${attr(id)}">${icon('edit')}Edit details</button><button class="button button-outline" data-action="read-card" data-id="${attr(id)}">${icon('download')}Read & back up</button><button class="button button-primary" data-action="choose-recipe" data-id="${attr(id)}" ${!backups.length?'disabled':''}>${icon('recipe')}Prepare recipe</button></div>`,{wide:true,prefix:'CARD INVENTORY'});state.modalContext={type:'card',id,backups};renderInitializationEntry(card,backups);}catch(e){closeModal();toast(e.message,true);}}
function importCardBackup(id){const card=state.cards.find(c=>String(c.id)===String(id));openModal('Save a card backup',`Import a reference Proxmark JSON dump for ${card?.label||'this card'}.`,`${callout('Imported dumps support recipe previews. A fresh read through your Windows bridge is still required before a physical write or restore.','warning')}<form id="backup-form"><div class="file-drop">${icon('upload')}<label for="backup-file">Choose a Proxmark JSON dump.</label><input id="backup-file" type="file" accept="application/json,.json"></div><div class="field"><label for="backup-json">Dump contents</label><textarea id="backup-json" class="code-area" spellcheck="false" required placeholder='{"Created":"proxmark3","FileType":"15693 v4",…}'></textarea></div><label class="check-field"><input type="checkbox" required>I have checked that this dump corresponds to the card labeled “${esc(card?.label)}”.</label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="view-card" data-id="${attr(id)}">Back</button><button class="button button-primary" type="submit">${icon('shield')}Save backup</button></div></form>`,{wide:true});$('#backup-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(file){if(file.size>2*1024*1024){toast('Choose a JSON file smaller than 2 MB.',true);return;}$('#backup-json').value=await file.text();}});$('#backup-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{let dump;try{dump=JSON.parse($('#backup-json').value);}catch{throw new Error('This is not valid JSON. Choose the .json version of your Proxmark dump.');}await api(`/api/cards/${encodeURIComponent(id)}/backups`,{method:'POST',body:{dump}});await refresh({renderPage:false});await viewCard(id);toast('Card backup saved.');});});}
function chooseCard(recipeId){if(!state.cards.length){toast('Register a card and save a backup first.');location.hash='cards';closeModal();return;}openModal('Choose a card','Pick the labeled physical card you want to prepare.',`<div class="recipe-list">${state.cards.map(c=>`<div class="version-item"><div><strong>${esc(c.label)}</strong><p>${esc(cardBackupState(c).label)}</p></div><button class="button button-small button-outline" data-action="prepare-card" data-id="${attr(c.id)}" data-recipe="${attr(recipeId)}" ${!num(c.backup_count)?'disabled':''}>Review ${icon('arrow')}</button></div>`).join('')}</div>`,{narrow:true});}
function chooseRecipe(cardId){if(!state.recipes.length){toast('Create a recipe in your library first.');closeModal();location.hash='recipes';return;}openModal('Choose a recipe',`Prepare a recipe for ${cardLabel(cardId)}.`, `<div class="recipe-list">${state.recipes.map(r=>`<div class="version-item"><div><strong>${esc(r.name)}</strong><p>${fmt(r.dose_g)} g · ${fmt(r.total_water_ml)} ml · Version ${r.version||1}</p></div><button class="button button-small button-outline" data-action="prepare-card" data-id="${attr(cardId)}" data-recipe="${attr(r.id)}">Review ${icon('arrow')}</button></div>`).join('')}</div>`);}
async function prepareCard(cardId,recipeId){showModalLoading('Review your card recipe');try{const preview=await api(`/api/cards/${encodeURIComponent(cardId)}/preview`,{method:'POST',body:{recipe_id:recipeId}});const card=state.cards.find(c=>String(c.id)===String(cardId));const recipe=state.recipes.find(r=>String(r.id)===String(recipeId));openModal('Review the card write',`${recipe?.name||'Recipe'} → ${card?.label||'Card'}`,`${recipe?recipeMetrics(recipe):''}${previewHtml(preview)}${callout('Only this reviewed recipe version should be written. Card-specific identity and header data must be preserved.','info')}<div class="form-actions"><button class="button button-outline" data-action="view-card" data-id="${attr(cardId)}">Back to card</button><button class="button button-primary" data-action="confirm-write" data-id="${attr(cardId)}" data-recipe="${attr(recipeId)}" ${preview.compatible===false||preview.errors?.length?'disabled':''}>Continue to confirmation ${icon('arrow')}</button></div>`,{wide:true});state.modalContext={type:'preview',cardId,recipeId,preview,version:preview.recipe_version||recipe?.version};}catch(e){closeModal();toast(e.message,true);}}
function confirmJob(kind,cardId,{recipeId=null,backupId=null}={}){
  const card=state.cards.find(c=>String(c.id)===String(cardId));if(!card)return;
  const isRead=kind==='read',bridge=state.status.bridge||{},previous=state.modalContext;
  const simulated=isSimulation(bridge);
  const recipe=state.recipes.find(r=>String(r.id)===String(recipeId));
  const reviewedVersion=previous?.version||recipe?.version;
  const differences=kind==='write'?(previous?.preview?.differences||[]):[];
  openModal(simulated?`Simulate a card ${kind}`:isRead?'Read and back up this card':kind==='restore'?'Confirm a card restore':'Confirm this card write',simulated?'This job uses simulated card memory. No physical card or Proxmark will be accessed.':isRead?'A read saves the card’s current contents without changing it.':'Approval applies to this one job and this labeled physical card.',
    `${!bridge.online?callout('Start the Windows bridge before creating this job. A fresh connection is required for approval.','warning'):isSimulation(bridge)?callout('The bridge is in simulation mode. This job will not modify a physical card.','warning'):''}
    <div class="note-block"><h4>${esc(card.label)}</h4><p>UID: <span class="mono">${known(card.uid,'Not read yet')}</span>${recipeId?`<br>Recipe: ${esc(recipeName(recipeId))}${reviewedVersion?` · Version ${reviewedVersion}`:''}`:''}${backupId?`<br>Restore backup: <span class="mono">${esc(backupId)}</span>`:''}</p></div>
    ${differences.length?previewHtml(previous.preview):''}
    <form id="job-form">
      ${!isRead?field('confirm_label',simulated?'Type the simulated card label to confirm':'Type the physical card label to confirm','','text',`required autocomplete="off" placeholder="${attr(card.label)}"`):''}
      <label class="check-field"><input type="checkbox" name="confirm" required>${simulated?`I approve a simulated ${kind} for “${esc(card.label)}”. No physical card or Proxmark will be accessed.`:isRead?`The card labeled “${esc(card.label)}” is the only card on the Proxmark.`:`I have placed the card labeled “${esc(card.label)}” on the Proxmark. I approve this ${kind==='restore'?'restore':'write'} and its read-back verification.`}</label>
      ${differences.length?'<label class="check-field"><input type="checkbox" name="accept_encoding_changes" required>I accept the listed differences between my intended recipe and the recipe encoded on this card.</label>':''}
      <div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="view-card" data-id="${attr(cardId)}">Cancel</button><button class="button ${kind==='restore'?'button-danger':'button-primary'}" type="submit" ${!bridge.online?'disabled':''}>${icon(isRead?'download':kind==='restore'?'refresh':'card')}${simulated?`Queue simulated ${kind}`:isRead?'Queue card read':kind==='restore'?'Approve restore':'Approve this write'}</button></div>
    </form>`,{wide:differences.length>0});
  $('#job-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{
    const fd=new FormData(e.target);
    if(!isRead&&fd.get('confirm_label')!==card.label)throw new Error(simulated?'The label must match this simulated card exactly.':'The label must match exactly. Check the physical card before approving.');
    const body={kind,card_id:cardId,confirm:true,bridge_mode:bridge.mode};
    if(!isRead)body.confirm_label=fd.get('confirm_label');
    if(recipeId){body.recipe_id=recipeId;body.version=reviewedVersion;body.accept_encoding_changes=fd.get('accept_encoding_changes')==='on';}
    if(backupId)body.backup_id=backupId;
    const job=await api('/api/jobs',{method:'POST',body});closeModal();await refresh();
    toast(`${human(kind)} request queued.${job.mode==='simulation'?' Simulation only.':' Follow its progress in NFC cards.'}`);location.hash='cards';
  });});
}
async function chooseInitialization(cardId){
  const card=state.cards.find(c=>String(c.id)===String(cardId));if(!card)return;
  if(!state.recipes.length){toast('Save the recipe you want on this card first.');return;}
  showModalLoading('Prepare a blank card');
  const context={type:'initialize-select',cardId};state.modalContext=context;
  try{
    const [status,targetResult]=await Promise.all([api('/api/status'),api(`/api/cards/${encodeURIComponent(cardId)}/backups`)]);
    if(state.modalContext!==context)return;
    state.status=status;const mode=initializationMode(),baseline=newestModeBackup(list(targetResult),mode);
    if(initializationBlocked(card,mode)||!initializationCandidate(baseline,mode,'blank'))throw new Error('This card needs a successful fresh read of a supported blank card before initialization can be reviewed.');
    const sourceCards=state.cards.filter(c=>c.type==='custom'&&String(c.id)!==String(cardId)&&!initializationManualReview(c,mode));
    const sourceResults=await Promise.all(sourceCards.map(async source=>({card:source,backups:list(await api(`/api/cards/${encodeURIComponent(source.id)}/backups`))})));
    if(state.modalContext!==context)return;
    const templates=sourceResults.map(({card:source,backups})=>({card:source,backup:[...backups].sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||''))).find(b=>initializationCandidate(b,mode,'template'))})).filter(item=>item.backup).sort((a,b)=>String(b.backup.created_at||'').localeCompare(String(a.backup.created_at||'')));
    if(!templates.length){openModal('A saved template is needed',card.label,`${callout('Read and back up another working custom card in the same bridge mode. Its valid, nonblank identity header becomes the template. Imported dumps and failed readbacks cannot be used.','warning')}<div class="form-actions">${button('view-card','Back to card','arrow','outline',`data-id="${attr(cardId)}"`)}</div>`);state.modalContext=null;return;}
    openModal(mode==='simulation'?'Prepare simulated initialization':'Prepare a blank card',`Choose the identity template and recipe for ${card.label}.`,
      `${mode==='simulation'?callout('Simulation only. No physical card or Proxmark will be accessed.','warning'):''}${callout('This is a separate blank-card operation. It changes the card’s UID and header, writes the recipe, and changes two hidden chip settings. The next screen shows every change before approval.','warning')}
      <div class="note-block"><h4>${esc(card.label)}</h4><p>Original UID: <span class="mono">${esc(baseline.uid)}</span><br>Original memory backup is retained.</p></div>
      <form id="initialization-select-form"><div class="field-grid"><div class="span-full">${selectField('template_backup_id','Identity template',templates[0].backup.id,templates.map(t=>[t.backup.id,`${t.card.label} · ${t.backup.uid} · ${date(t.backup.created_at,true)}`]))}</div><div class="span-full">${selectField('recipe_id','Recipe to put on the blank card',state.recipes[0].id,state.recipes.map(r=>[r.id,`${r.name} · version ${r.version} · ${fmt(r.dose_g)} g / ${fmt(r.total_water_ml)} ml`]))}</div></div><p class="muted">The newest valid saved backup for each other custom card is listed. The template card stays unchanged and should be kept off the reader.</p><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="view-card" data-id="${attr(cardId)}">Cancel</button><button type="submit" class="button button-primary">Review initialization ${icon('arrow')}</button></div></form>`,{wide:true});
    state.modalContext=context;
    $('#initialization-select-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{
      const fd=new FormData(e.target),template=templates.find(t=>String(t.backup.id)===fd.get('template_backup_id')),recipe=state.recipes.find(r=>String(r.id)===fd.get('recipe_id'));
      if(!template||!recipe)throw new Error('Choose a saved template and recipe.');
      const request={template_backup_id:template.backup.id,recipe_id:recipe.id,version:recipe.version,bridge_mode:mode,chip_profile:initializationProfile};
      const preview=await api(`/api/cards/${encodeURIComponent(cardId)}/initialize-preview`,{method:'POST',body:request});
      if(state.modalContext!==context)return;
      reviewInitialization(card,recipe,template,request,preview);
    });});
  }catch(e){if(state.modalContext===context){closeModal();toast(e.message,true);}}
}
function initializationRecipeHtml(recipe){
  return `${recipeMetrics(recipe)}<div class="badge-row"><span class="pill gray">${esc(human(recipe.cup_type))}</span><span class="pill gray">${recipe.grinder_enabled===false?'Grinder off':`${fmt(recipe.grinder_rpm)} RPM`}</span></div><div class="table-wrap"><table><thead><tr><th>Pour</th><th>Water</th><th>Temperature</th><th>Flow</th><th>Pattern</th><th>Pause after</th><th>Agitation</th></tr></thead><tbody>${recipe.pours.map((p,i)=>`<tr><td>${i+1}</td><td>${fmt(p.volume_ml)} ml</td><td>${fmt(p.temperature_c)} °C</td><td>${fmt(p.flow_ml_s)} ml/s</td><td>${esc(human(p.pattern))}</td><td>${fmt(p.pause_s)} s</td><td>${p.agitation_before&&p.agitation_after?'Before and after':p.agitation_before?'Before':p.agitation_after?'After':'None'}</td></tr>`).join('')}</tbody></table></div>`;
}
function updateInitializationAvailability(){
  const context=state.modalContext;if(context?.type!=='initialize-preview')return;
  const ready=initializationBridgeReady(context.request.bridge_mode),submit=$('#initialize-submit'),status=$('#initialize-bridge-status');
  if(submit)submit.disabled=!ready||submitting;
  if(status)status.textContent=ready?(context.request.bridge_mode==='simulation'?'Simulation bridge ready. No physical card will change.':'Initialization-enabled bridge connected. A second confirmation is required at your Windows PC.'):'Approval is unavailable. Start an initialization-enabled bridge in the reviewed mode, then refresh its status.';
}
function reviewInitialization(card,recipe,template,request,preview){
  const plan=preview.initialization_context,special=preview.special_configuration_writes;
  if(preview.compatible!==true||!plan||String(plan.card_id)!==String(card.id)||String(plan.template_backup_id)!==String(template.backup.id)||String(plan.recipe_id)!==String(recipe.id)||plan.recipe_version!==request.version||plan.mode!==request.bridge_mode||plan.card_label!==card.label||plan.template_label!==template.card.label||!preview.preview_sha256||preview.hidden_configuration_backup_available!==false||!Array.isArray(special)||special.length!==2||special[0].selector!=='47'||special[0].data!=='3F038B00'||special[1].selector!=='52'||special[1].data!=='00000000'||!Array.isArray(preview.write_blocks)||!Array.isArray(preview.effective?.pours))throw new Error('The initialization preview is incomplete or changed. Read the card again and request a new review.');
  const simulated=request.bridge_mode==='simulation',context={type:'initialize-preview',request,preview};
  openModal(simulated?'Review simulated initialization':'Review blank-card initialization',`${recipe.name} · version ${plan.recipe_version} → ${plan.card_label}`,
    `${simulated?callout('Simulation only. No physical card or Proxmark will be accessed.','warning'):''}${callout('This changes two hidden chip settings. The saved 64-block backup does not contain their original values and cannot restore them. Normal readback cannot verify their final values.','danger','A separate configuration change.')}
    <dl class="info-grid"><div><dt>Target card</dt><dd>${esc(plan.card_label)}</dd></div><div><dt>Original UID</dt><dd class="mono">${esc(preview.original_uid)}</dd></div><div><dt>Identity template</dt><dd>${esc(plan.template_label)}</dd></div><div><dt>New UID</dt><dd class="mono">${esc(preview.target_uid)}</dd></div></dl>
    <p>The template’s 32-byte header is copied to the blank card. The template card is not written. Keep only <strong>${esc(plan.card_label)}</strong> on the reader.</p>
    <a class="text-link" href="/api/cards/${encodeURIComponent(card.id)}/backups/${encodeURIComponent(plan.original_backup_id)}/download" download>${icon('download')}Download retained original memory backup</a>
    <section class="form-section"><h3>Exact recipe on the card</h3>${initializationRecipeHtml(preview.effective)}${previewHtml({...preview,effective:{}})}${recipe.dripper||recipe.filter?`<p>Brewing setup: ${[recipe.dripper,recipe.filter].filter(Boolean).map(esc).join(' · ')}.</p>`:''}${recipe.notes?`<div class="note-block"><h4>Preparation and recipe notes · not encoded on the card</h4><p>${esc(recipe.notes).replaceAll('\n','<br>')}</p></div>`:''}</section>
    <section class="form-section"><h3>Hidden settings to be changed</h3><div class="table-wrap"><table><thead><tr><th>Setting</th><th>Original</th><th>Value to write</th></tr></thead><tbody>${special.map(s=>`<tr><td><code>${esc(s.selector)}</code></td><td>Not backed up</td><td><code>${esc(s.data)}</code></td></tr>`).join('')}</tbody></table></div><p>These are chip-setting selectors, not ordinary memory block numbers. The visible memory from byte 160 onward, readable lock states, and AFI/DSFID/IC metadata must remain unchanged.</p></section>
    <details><summary>Review ${preview.write_blocks.length} visible memory block changes</summary><div class="details-content table-wrap"><table><thead><tr><th>Block</th><th>Before</th><th>After</th></tr></thead><tbody>${preview.write_blocks.map(b=>`<tr><td>${esc(b.block)}${num(b.block)<8?' · Header':' · Recipe'}</td><td><code>00000000</code></td><td><code>${esc(b.data)}</code></td></tr>`).join('')}</tbody></table></div></details>
    ${callout('Successful readback verifies the readable card data only. Whether your offline xBloom accepts the new card and follows its recipe remains unknown until you test it. Bluetooth is not used.','warning','Machine acceptance is still untested.')}
    <form id="initialization-confirm-form"><div class="field-grid">${field('confirm_label','Type the target card label','','text',`required autocomplete="off" placeholder="${attr(plan.card_label)}"`)}${field('confirm_template_label','Type the template card label','','text',`required autocomplete="off" placeholder="${attr(plan.template_label)}"`)}</div>
    <label class="check-field"><input type="checkbox" name="confirm_initialize" required>${simulated?'I approve this simulated initialization only.':'I approve this one initialization, including the displayed UID, header, and recipe changes, for the labeled blank card.'}</label>
    <label class="check-field"><input type="checkbox" name="accept_special_configuration_changes" required>I explicitly accept the two hidden chip-setting changes. I understand that this backup cannot recover them and normal readback cannot verify them.</label>
    <label class="check-field"><input type="checkbox" name="accept_unverified_machine" required>I understand that card readback does not prove acceptance by the offline xBloom.</label>
    ${(preview.differences||[]).length?'<label class="check-field"><input type="checkbox" name="accept_encoding_changes" required>I accept the listed recipe encoding differences.</label>':''}
    <p id="initialize-bridge-status" role="status" aria-live="polite"></p><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="view-card" data-id="${attr(card.id)}">Cancel</button><button type="submit" id="initialize-submit" class="button button-danger" disabled>${icon('card')}${simulated?'Approve simulated initialization':'Approve this initialization'}</button></div></form>`,{wide:true,prefix:'SEPARATE BLANK-CARD APPROVAL'});
  state.modalContext=context;updateInitializationAvailability();
  $('#initialization-confirm-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target;await withForm(form,async()=>{
    if(state.modalContext!==context)throw new Error('Request a fresh initialization review.');
    const fd=new FormData(form);
    if(fd.get('confirm_label')!==plan.card_label||fd.get('confirm_template_label')!==plan.template_label)throw new Error('Both labels must match exactly. Check the physical target and template labels.');
    if(fd.get('confirm_initialize')!=='on'||fd.get('accept_special_configuration_changes')!=='on'||fd.get('accept_unverified_machine')!=='on'||((preview.differences||[]).length&&fd.get('accept_encoding_changes')!=='on'))throw new Error('Review and accept each confirmation before approving.');
    state.status=await api('/api/status');
    if(state.modalContext!==context)return;
    if(!initializationBridgeReady(request.bridge_mode))throw new Error('The reviewed initialization-enabled bridge is not available. Restore that connection before approving.');
    const job=await api('/api/jobs',{method:'POST',body:{...request,kind:'initialize',card_id:card.id,confirm:true,confirm_initialize:true,confirm_label:fd.get('confirm_label'),confirm_template_label:fd.get('confirm_template_label'),expected_preview_sha256:preview.preview_sha256,accept_special_configuration_changes:fd.get('accept_special_configuration_changes')==='on',accept_encoding_changes:fd.get('accept_encoding_changes')==='on'}});
    closeModal();await refresh();toast(job.mode==='simulation'?'Simulated initialization queued. No physical card will change.':'Initialization queued. Confirm this exact operation at the Windows bridge.');location.hash='cards';
  });updateInitializationAvailability();});
}
function resolveJob(id){
  const job=state.jobs.find(j=>String(j.id)===String(id));if(!job)return;
  openModal('Resolve an interrupted card job','Stop the Windows bridge before clearing this interrupted operation.',
    `${callout(job.kind==='initialize'?'The application cannot determine the card’s identity or hidden settings after this interruption. Resolving marks initialization as failed and requires manual identity review. A fresh read records evidence but does not allow another write or automatic retry.':'The application cannot determine whether this card was fully written. Resolving marks the operation as failed and requires a fresh read before another write. It does not retry the operation.','warning')}
    <div class="note-block"><h4>${esc(job.label||cardLabel(job.card_id))}</h4><p>${esc(human(job.kind))} · started ${date(job.started_at||job.created_at,true)}</p></div>
    <form id="resolve-form">${field('confirm_label','Physical card label','','text','required autocomplete="off"')}
    <label class="check-field"><input type="checkbox" name="confirm_bridge_stopped" required>I have fully stopped the Windows bridge process and confirmed it is no longer performing a card operation.</label>
    <div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-danger" type="submit">${icon('warning')}${job.kind==='initialize'?'Mark interrupted & require manual review':'Mark interrupted & require new read'}</button></div></form>`);
  $('#resolve-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{
    const fd=new FormData(e.target);await api(`/api/jobs/${encodeURIComponent(id)}/resolve`,{method:'POST',body:{confirm_bridge_stopped:fd.get('confirm_bridge_stopped')==='on',confirm_label:String(fd.get('confirm_label')||'')}});closeModal();await refresh();toast(job.kind==='initialize'?'Initialization marked interrupted. Manual identity review is required.':'Interrupted job resolved. Read the card again before writing.');
  });});
}

// Settings and utility dialogs
function bridgeHelp(){openModal('Connect your Windows bridge','The bridge links your local server to the USB Proxmark on your PC.',`${callout('Start in simulation mode. Enable hardware writes only after validating the client path, card reads, and local backups.','info')}<ol class="data-list"><li>Create a bridge token in Settings. It is shown only once.</li><li>On your Windows PC, open the project’s bridge setup instructions and configure the server’s LAN URL, bridge token, Proxmark client path, and USB port.</li><li>Start the bridge and confirm that its status appears online here.</li><li>Register a physical card, read its contents, and review the saved backup.</li><li>Review a recipe’s NFC representation. Each write or restore requires a separate confirmation.</li><li>Blank-card initialization has its own review and bridge opt-in. It changes identity and two hidden chip settings that the memory backup cannot recover.</li></ol><div class="note-block"><h4>Use your current reader setup</h4><p>Verify the connected reader’s firmware, compatible Iceman/RRG client, and current USB port. A previous computer’s client or port is not a default.</p></div><p class="muted" style="font-size:11px">The bridge makes outbound requests to this application. Keep the Proxmark interface private on Windows.</p><div class="form-actions"><button class="button button-primary" data-action="close-modal">Got it</button></div>`);}
async function createToken(kind){openModal(kind==='bridge'?'Create a Windows bridge token':'Create an import API token','This grants access to the local application. Store it securely.',`<form id="token-form">${callout(kind==='bridge'?'Use a bridge token only in the Windows Proxmark bridge configuration.':'Use this token when transferring a reviewed coffee profile from Codex.','info')}${state.settings.tokens_configured?.includes(kind)?callout('Creating a new token revokes the existing token of this type. Update the client configuration after copying it.','warning'):''}<label class="check-field"><input type="checkbox" required>I will keep this token out of GitHub and shared files.</label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">${icon('lock')}Create token</button></div></form>`,{narrow:true});$('#token-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const result=await api('/api/tokens',{method:'POST',body:{kind}});openModal('Copy your token now','It will not be shown again after this dialog closes.',`${callout('Save this token in your local configuration or password manager. Never commit it to your repository.','warning')}<div class="field"><label for="generated-token">${kind==='bridge'?'Bridge':'Import API'} token</label><textarea id="generated-token" class="mono" readonly rows="3" spellcheck="false">${esc(result.token)}</textarea></div><div class="form-actions"><button class="button button-outline" data-action="copy-token">${icon('copy')}Copy token</button><button class="button button-primary" data-action="close-modal">I’ve saved it</button></div>`);});});}
function importFormat(){openModal('The coffee profile format','JSON is an optional way to import a profile prepared with Codex. You can also start from a product link.',`${callout('This is a synthetic example. Replace it with verified product details and your reviewed recipe before importing.','warning')}<div class="field"><label for="format-json">Example profile</label><textarea id="format-json" class="code-area" readonly spellcheck="false">${esc(JSON.stringify(sampleProfile(),null,2))}</textarea></div><div class="note-block mt-16"><h4>Authenticated import API</h4><p>Use <code>Authorization: Bearer YOUR_API_TOKEN</code>. Validate the profile with <code>POST /api/import/preview</code>, then save an approved profile with <code>POST /api/import/approve</code>. Both requests include a <code>profile</code> object; approval also requires <code>approved: true</code>.</p></div><div class="form-actions"><button class="button button-outline" data-action="copy-format">${icon('copy')}Copy example</button><button class="button button-primary" data-action="import">Import a profile</button></div>`,{wide:true});}
function confirmDelete(resource,id){const object=state[resource].find(r=>String(r.id)===String(id));if(!object)return;openModal(`Delete ${resource==='beans'?'coffee':resource==='recipes'?'recipe':'card record'}?`,`“${object.name||object.label}” will be removed from your workspace.`,`${callout(resource==='cards'?'This deletes the inventory record only. It does not change the physical card. Records with saved history may be protected from deletion.':'Related records may prevent deletion. The application will explain if this item is still in use.','warning')}<form id="delete-form"><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Keep it</button><button class="button button-danger" type="submit">${icon('trash')}Delete record</button></div></form>`,{narrow:true});$('#delete-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{await api(`/api/${resource}/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal();await refresh();toast('Record deleted.');});});}
async function copyText(text){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);}else{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';(modal.open?$('#modal-content'):document.body).append(input);input.select();const ok=document.execCommand('copy');input.remove();if(!ok)throw new Error('Select the text and copy it manually.');}toast('Copied to clipboard.');}
async function action(name,el){const id=el?.dataset.id;switch(name){
  case 'close-modal':closeModal();break;
  case 'new-bean':editBean();break;case 'edit-bean':editBean(id);break;case 'view-bean':viewBean(id);break;
  case 'new-recipe':editRecipe(null,el?.dataset.bean);break;case 'edit-recipe':editRecipe(id);break;case 'view-recipe':await viewRecipe(id);break;case 'recipe-version':await viewRecipe(id,el.dataset.version);break;
  case 'delete-bean':confirmDelete('beans',id);break;case 'delete-recipe':confirmDelete('recipes',id);break;case 'delete-card':confirmDelete('cards',id);break;
  case 'new-card':editCard();break;case 'edit-card':editCard(id);break;case 'view-card':await viewCard(id);break;
  case 'import':importProfile();break;case 'back-import':importProfile(state.importProfile);break;
  case 'load-example':importProfile(sampleProfile(),{warnings:['Synthetic example. Replace its details before saving.']});break;
  case 'import-add-pour':{const form=$('#import-form');const pours=readPours(form);if(pours.length>=20)throw new Error('Use no more than 20 pours.');pours.push({volume_ml:60,temperature_c:94,flow_ml_s:3.5,pattern:'circle',pause_s:0,agitation_before:false,agitation_after:false});$('#pour-editors',form).innerHTML=pours.map((p,i)=>pourEditor(p,i).replace('data-action="remove-pour"','data-action="import-remove-pour"')).join('');state.importProfile=readImportDraft(form);updateRecipeTotals(form);break;}
  case 'import-remove-pour':{const form=$('#import-form');el.closest('.step-editor').remove();state.importProfile=readImportDraft(form);updateRecipeTotals(form);break;}
  case 'initialize-card':await chooseInitialization(id);break;case 'import-card-backup':importCardBackup(id);break;case 'read-card':confirmJob('read',id);break;case 'restore-card':confirmJob('restore',id,{backupId:el.dataset.backup});break;
  case 'choose-card':chooseCard(id);break;case 'choose-recipe':chooseRecipe(id);break;case 'prepare-card':await prepareCard(id,el.dataset.recipe);break;case 'confirm-write':confirmJob('write',id,{recipeId:el.dataset.recipe});break;
  case 'add-pour':{const container=$('#pour-editors');const pours=readPours($('#recipe-form'));pours.push({volume_ml:50,temperature_c:92,flow_ml_s:3.5,pattern:'circle',pause_s:0,agitation_before:false,agitation_after:false});container.innerHTML=pours.map(pourEditor).join('');updateRecipeTotals($('#recipe-form'));$('#recipe-preview').innerHTML='';break;}
  case 'remove-pour':{const form=$('#recipe-form'),pour=el.closest('.step-editor'),index=Number(pour.dataset.pour),pours=readPours(form);if(pours.length===1){toast('Keep at least one pour.',true);break;}pours.splice(index,1);$('#pour-editors').innerHTML=pours.map(pourEditor).join('');updateRecipeTotals(form);$('#recipe-preview').innerHTML='';break;}
  case 'preview-recipe':{const form=$('#recipe-form');if(!form.reportValidity())break;el.disabled=true;try{const preview=await api('/api/recipes/preview',{method:'POST',body:recipeFromForm(form)});$('#recipe-preview').innerHTML=previewHtml(preview);$('#recipe-preview').scrollIntoView({behavior:'smooth',block:'nearest'});}finally{el.disabled=false;}break;}
  case 'refresh':await refresh();toast('Workspace refreshed.');break;
  case 'cancel-job':await api(`/api/jobs/${encodeURIComponent(id)}/cancel`,{method:'POST'});await refresh();toast('Queued card job cancelled.');break;
  case 'resolve-job':resolveJob(id);break;
  case 'bridge-help':bridgeHelp();break;case 'create-api-token':await createToken('api');break;case 'create-bridge-token':await createToken('bridge');break;
  case 'copy-token':await copyText($('#generated-token').value);break;case 'import-format':importFormat();break;case 'copy-format':await copyText($('#format-json').value);break;
  case 'logout':if(trustedLan())break;await api('/api/session',{method:'DELETE'});state.session=await api('/api/session');showAuth();break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();action(el.dataset.action,el).catch(err=>toast(err.message,true));}});
document.addEventListener('input',e=>{if(e.target.id==='page-search'){const pos=e.target.selectionStart;state.query=e.target.value;render();const search=$('#page-search');search.focus();try{search.setSelectionRange(pos,pos);}catch{}}});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#nav-backdrop').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#nav-backdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#nav-backdrop').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');});
$('#session-button').addEventListener('click',()=>location.hash='settings');
modal.addEventListener('cancel',e=>{if(!state.session.authenticated)e.preventDefault();else document.body.classList.remove('login-only');});
modal.addEventListener('click',e=>{if(e.target===modal&&state.session.authenticated){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',changeRoute);
async function init(){hydrateIcons();changeRoute();renderNavigation();try{state.session=await api('/api/session');if(state.session.authenticated)await refresh();else showAuth();}catch(e){$('#main').innerHTML=`<div class="error-state"><h2>The workspace is taking a moment.</h2><p>${esc(e.message)}</p><button class="button button-outline" data-action="refresh">${icon('refresh')}Try again</button></div>`;}setInterval(()=>{if(state.session.authenticated&&!document.hidden)refresh({renderPage:!modal.open&&!state.query&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName),quiet:true});},30000);}
init();
